-- ===== 20261013000100_foundation.sql =====
-- =============================================================================
-- Phase 1 · Foundation: extensions, schemas, enums, shared trigger functions.
--
-- Timezone: every timestamp is stored as timestamptz (UTC on disk). Anything
-- that needs a *local* notion of "day" or "time of day" converts explicitly
-- with AT TIME ZONE 'America/Los_Angeles' — never rely on the session TZ.
-- =============================================================================

create extension if not exists btree_gist with schema extensions;

-- Helper functions used by RLS policies live in `private`, which is NOT exposed
-- through the PostgREST API (only `public` is). Clients cannot call them as RPCs.
create schema if not exists private;
revoke all on schema private from public;
grant usage on schema private to anon, authenticated, service_role;

-- -----------------------------------------------------------------------------
-- Enums
-- -----------------------------------------------------------------------------
create type public.user_role as enum ('parent', 'instructor', 'admin');

create type public.swim_level as enum (
  'water_acclimation',   -- new to water / fearful
  'beginner',
  'advanced_beginner',
  'intermediate',
  'advanced',
  'stroke_technique'
);

create type public.booking_status as enum (
  'pending_payment',     -- slot held while Stripe Checkout is open
  'pending_instructor',  -- paid, waiting for instructor to accept the request
  'confirmed',
  'completed',
  'cancelled',
  'no_show',
  'expired'              -- payment hold or instructor offer chain ran out
);

create type public.booking_kind as enum ('single', 'package', 'recurring', 'manual');

create type public.availability_override_kind as enum ('available', 'blackout');

create type public.offer_status as enum ('pending', 'accepted', 'declined', 'expired', 'superseded');

create type public.open_shift_status as enum (
  'open',
  'pending_approval',    -- claimed; waiting on admin (when approval is required)
  'filled',
  'cancelled',
  'expired'
);

create type public.payment_status as enum (
  'pending', 'succeeded', 'failed', 'refunded', 'partially_refunded', 'cancelled'
);

create type public.package_status as enum ('pending_payment', 'active', 'exhausted', 'expired', 'refunded');

create type public.series_status as enum ('pending_payment', 'active', 'paused', 'cancelled', 'ended');

create type public.certification_kind as enum (
  'cpr', 'first_aid', 'lifeguard', 'water_safety_instructor', 'swim_instructor', 'background_check', 'other'
);

create type public.earning_status as enum ('pending', 'approved', 'paid', 'void');

create type public.flag_reason as enum ('phone', 'email', 'social_handle', 'payment_app', 'url', 'off_platform_language');

create type public.flag_status as enum ('open', 'reviewed', 'actioned', 'dismissed');

create type public.inquiry_status as enum (
  'new', 'contacted', 'approved', 'payment_link_sent', 'paid', 'declined', 'closed'
);

create type public.interest_level as enum ('just_curious', 'interested', 'ready_to_book');

-- -----------------------------------------------------------------------------
-- Shared trigger functions
-- -----------------------------------------------------------------------------
create or replace function private.set_updated_at()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  new.updated_at := now();
  return new;
end;
$$;

-- Local (America/Los_Angeles) calendar date of a timestamptz.
create or replace function private.la_date(ts timestamptz)
returns date
language sql
immutable
set search_path = ''
as $$
  select (ts at time zone 'America/Los_Angeles')::date
$$;

-- Midnight America/Los_Angeles at the start of the local day containing `ts`.
create or replace function private.la_day_start(ts timestamptz)
returns timestamptz
language sql
immutable
set search_path = ''
as $$
  select (date_trunc('day', ts at time zone 'America/Los_Angeles')) at time zone 'America/Los_Angeles'
$$;

-- Address reveal window (pure function so it can be unit-tested with fixed
-- clocks): visible from local midnight of the lesson day until
-- `hide_after_minutes` after the lesson ends.
create or replace function private.address_window_open(
  starts_at timestamptz,
  ends_at timestamptz,
  at_time timestamptz,
  hide_after_minutes integer
)
returns boolean
language sql
immutable
set search_path = ''
as $$
  select at_time >= private.la_day_start(starts_at)
     and at_time <= ends_at + make_interval(mins => hide_after_minutes)
$$;

-- Random URL-safe token without requiring pgcrypto (2 × UUIDv4 ≈ 244 random bits).
create or replace function private.random_token()
returns text
language sql
volatile
set search_path = ''
as $$
  select replace(gen_random_uuid()::text || gen_random_uuid()::text, '-', '')
$$;

-- ===== 20261013000200_core_schema.sql =====
-- =============================================================================
-- Phase 1 · Core schema
--
-- Design rule for client insulation: data an instructor must never see lives in
-- tables they have NO row access to. Columns are never "hidden" in a table an
-- instructor can read. Concretely:
--   users              email / phone / last name           → self + admin only
--   parents            home address, Stripe ids            → self + admin only
--   booking_locations  lesson street address               → parent + admin; instructor
--                                                             only via audited RPC, day-of
--   booking_pricing    what the parent paid                → parent + admin only
--   instructor_private pay rate, iCal token                → self + admin only
-- =============================================================================

-- -----------------------------------------------------------------------------
-- Platform configuration (singletons — every price/policy is editable in admin)
-- -----------------------------------------------------------------------------
create table public.platform_settings (
  id boolean primary key default true check (id),
  timezone text not null default 'America/Los_Angeles',
  cancellation_window_hours integer not null default 24 check (cancellation_window_hours >= 0),
  late_cancel_refund_pct numeric(5,2) not null default 0 check (late_cancel_refund_pct between 0 and 100),
  booking_request_window_hours integer not null default 12 check (booking_request_window_hours > 0),
  payment_hold_minutes integer not null default 20 check (payment_hold_minutes > 0),
  default_travel_buffer_minutes integer not null default 30 check (default_travel_buffer_minutes >= 0),
  default_instructor_pay_cents_per_hour integer not null default 4000 check (default_instructor_pay_cents_per_hour >= 0),
  sub_board_requires_approval boolean not null default true,
  address_hide_after_minutes integer not null default 120 check (address_hide_after_minutes >= 0),
  masked_number_ttl_minutes integer not null default 120 check (masked_number_ttl_minutes >= 0),
  instructor_terms_version text not null default '2026-10-01',
  max_children_per_lesson integer not null default 6 check (max_children_per_lesson > 0),
  max_lesson_view_range_days integer not null default 31 check (max_lesson_view_range_days between 1 and 92),
  support_email text,
  support_phone text,
  updated_at timestamptz not null default now(),
  updated_by uuid
);

create table public.pricing_config (
  id boolean primary key default true check (id),
  currency text not null default 'usd',
  included_children integer not null default 2 check (included_children >= 1),
  extra_child_cents integer not null default 2500 check (extra_child_cents >= 0),
  recurring_discount_pct numeric(5,2) not null default 10 check (recurring_discount_pct between 0 and 100),
  neighborhood_discount_cents integer not null default 500 check (neighborhood_discount_cents >= 0),
  neighborhood_window_minutes integer not null default 60 check (neighborhood_window_minutes >= 0),
  updated_at timestamptz not null default now(),
  updated_by uuid
);

create table public.lesson_prices (
  duration_minutes integer primary key check (duration_minutes > 0 and duration_minutes % 15 = 0),
  price_cents integer not null check (price_cents >= 0),
  label text,
  is_active boolean not null default true,
  sort_order integer not null default 0,
  updated_at timestamptz not null default now()
);

create table public.package_offerings (
  id uuid primary key default gen_random_uuid(),
  name text not null,
  lesson_count integer not null check (lesson_count > 1),
  discount_pct numeric(5,2) not null check (discount_pct between 0 and 100),
  validity_days integer not null default 180 check (validity_days > 0),
  is_active boolean not null default true,
  sort_order integer not null default 0,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (lesson_count)
);

-- -----------------------------------------------------------------------------
-- Zones
-- -----------------------------------------------------------------------------
create table public.zones (
  id uuid primary key default gen_random_uuid(),
  code text not null unique,                       -- 'A', 'B', 'C'
  name text not null,
  description text,
  travel_fee_cents integer not null default 0 check (travel_fee_cents >= 0),
  min_booking_minutes integer not null default 0 check (min_booking_minutes >= 0),
  is_bookable boolean not null default true,
  postal_codes text[] not null default '{}',
  neighborhoods text[] not null default '{}',
  boundary jsonb,                                  -- GeoJSON Polygon | MultiPolygon
  map_color text,
  sort_order integer not null default 0,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create index zones_postal_codes_gin on public.zones using gin (postal_codes);

create table public.zone_travel_buffers (
  from_zone_id uuid not null references public.zones (id) on delete cascade,
  to_zone_id uuid not null references public.zones (id) on delete cascade,
  buffer_minutes integer not null check (buffer_minutes >= 0),
  primary key (from_zone_id, to_zone_id)
);

-- -----------------------------------------------------------------------------
-- Users & roles
-- -----------------------------------------------------------------------------
create table public.users (
  id uuid primary key references auth.users (id) on delete cascade,
  role public.user_role not null default 'parent',
  email text not null,
  first_name text,
  last_name text,
  phone text check (phone is null or phone ~ '^\+[1-9][0-9]{7,14}$'),  -- E.164
  sms_opt_in boolean not null default false,
  email_opt_in boolean not null default true,
  onboarded_at timestamptz,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create index users_role_idx on public.users (role);
create index users_email_lower_idx on public.users (lower(email));

create table public.instructors (
  id uuid primary key references public.users (id) on delete cascade,
  display_name text not null,                      -- e.g. "Maya R." — never a full name
  bio text,
  photo_path text,                                 -- storage: instructor-photos/<id>/...
  specialties text[] not null default '{}',        -- toddlers, fearful_swimmers, stroke_technique, ...
  levels_taught public.swim_level[] not null default enum_range(null::public.swim_level),
  min_child_age_months integer not null default 6 check (min_child_age_months >= 0),
  max_children_per_lesson integer not null default 4 check (max_children_per_lesson > 0),
  years_experience integer check (years_experience >= 0),
  languages text[] not null default '{English}',
  is_active boolean not null default false,        -- admin activates after onboarding
  is_accepting_new_clients boolean not null default true,
  sort_order integer not null default 0,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create table public.instructor_private (
  instructor_id uuid primary key references public.instructors (id) on delete cascade,
  pay_rate_cents_per_hour integer not null default 4000 check (pay_rate_cents_per_hour >= 0),
  ical_feed_token text not null unique default private.random_token(),
  deactivated_at timestamptz,
  deactivation_reason text,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create table public.instructor_terms_acceptances (
  id uuid primary key default gen_random_uuid(),
  instructor_id uuid not null references public.instructors (id) on delete cascade,
  terms_version text not null,
  accepted_at timestamptz not null default now(),
  ip_address text,
  user_agent text,
  unique (instructor_id, terms_version)
);

create table public.instructor_invites (
  id uuid primary key default gen_random_uuid(),
  email text not null,
  invited_by uuid references public.users (id) on delete set null,
  pay_rate_cents_per_hour integer check (pay_rate_cents_per_hour >= 0),
  expires_at timestamptz not null default now() + interval '14 days',
  accepted_at timestamptz,
  accepted_user_id uuid references public.users (id) on delete set null,
  created_at timestamptz not null default now()
);

create index instructor_invites_email_idx on public.instructor_invites (lower(email)) where accepted_at is null;

create table public.instructor_certifications (
  id uuid primary key default gen_random_uuid(),
  instructor_id uuid not null references public.instructors (id) on delete cascade,
  kind public.certification_kind not null,
  issuer text,                                     -- e.g. "American Red Cross"
  issued_on date,
  expires_on date,
  document_path text,                              -- storage: certifications/<instructor_id>/...
  verified_at timestamptz,
  verified_by uuid references public.users (id) on delete set null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  check (expires_on is null or issued_on is null or expires_on >= issued_on)
);

create index instructor_certifications_instructor_idx on public.instructor_certifications (instructor_id);
create index instructor_certifications_expiry_idx on public.instructor_certifications (expires_on);

create table public.instructor_zones (
  instructor_id uuid not null references public.instructors (id) on delete cascade,
  zone_id uuid not null references public.zones (id) on delete cascade,
  created_at timestamptz not null default now(),
  primary key (instructor_id, zone_id)
);

create index instructor_zones_zone_idx on public.instructor_zones (zone_id);

-- -----------------------------------------------------------------------------
-- Parents & children
-- -----------------------------------------------------------------------------
create table public.parents (
  id uuid primary key references public.users (id) on delete cascade,
  stripe_customer_id text unique,
  favorite_instructor_id uuid references public.instructors (id) on delete set null,
  -- Default lesson address. Copied into booking_locations per booking.
  address_line1 text,
  address_line2 text,
  city text,
  state text default 'CA',
  postal_code text,
  lat double precision,
  lng double precision,
  google_place_id text,
  zone_id uuid references public.zones (id) on delete set null,
  neighborhood text,
  access_notes text,                               -- gate code, pool location, parking
  preferred_days smallint[] not null default '{}', -- 0 = Sunday … 6 = Saturday
  preferred_time_windows jsonb not null default '[]'::jsonb, -- [{"start":"15:00","end":"18:00"}]
  source text not null default 'web',              -- web | import:csv | import:acuity …
  external_id text,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create index parents_zone_idx on public.parents (zone_id);

create table public.children (
  id uuid primary key default gen_random_uuid(),
  parent_id uuid not null references public.parents (id) on delete cascade,
  first_name text not null check (length(trim(first_name)) between 1 and 60),
  birth_date date check (birth_date > date '1900-01-01'),
  swim_level public.swim_level not null default 'beginner',
  notes text,                                      -- shared with the assigned instructor
  is_active boolean not null default true,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create index children_parent_idx on public.children (parent_id);

-- -----------------------------------------------------------------------------
-- Availability
-- -----------------------------------------------------------------------------
create table public.availability_rules (
  id uuid primary key default gen_random_uuid(),
  instructor_id uuid not null references public.instructors (id) on delete cascade,
  weekday smallint not null check (weekday between 0 and 6),   -- 0 = Sunday (local)
  start_time time not null,                                     -- America/Los_Angeles wall clock
  end_time time not null,
  effective_from date not null default current_date,
  effective_until date,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  check (end_time > start_time),
  check (effective_until is null or effective_until >= effective_from)
);

create index availability_rules_instructor_idx on public.availability_rules (instructor_id, weekday);

create table public.availability_overrides (
  id uuid primary key default gen_random_uuid(),
  instructor_id uuid not null references public.instructors (id) on delete cascade,
  date date not null,                                           -- local date
  kind public.availability_override_kind not null,
  start_time time,                                              -- null + blackout = whole day
  end_time time,
  note text,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  check ((start_time is null) = (end_time is null)),
  check (start_time is null or end_time > start_time),
  check (kind = 'blackout' or start_time is not null)
);

create index availability_overrides_instructor_date_idx on public.availability_overrides (instructor_id, date);

-- -----------------------------------------------------------------------------
-- Packages & recurring series (purchases)
-- -----------------------------------------------------------------------------
create table public.packages (
  id uuid primary key default gen_random_uuid(),
  parent_id uuid not null references public.parents (id) on delete cascade,
  offering_id uuid references public.package_offerings (id) on delete set null,
  lesson_count integer not null check (lesson_count > 0),
  lessons_remaining integer not null check (lessons_remaining >= 0),
  duration_minutes integer not null check (duration_minutes > 0),
  children_count integer not null check (children_count > 0),
  zone_id uuid references public.zones (id) on delete set null,
  unit_price_cents integer not null check (unit_price_cents >= 0),
  discount_pct numeric(5,2) not null default 0,
  total_cents integer not null check (total_cents >= 0),
  status public.package_status not null default 'pending_payment',
  purchased_at timestamptz,
  expires_at timestamptz,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  check (lessons_remaining <= lesson_count)
);

create index packages_parent_idx on public.packages (parent_id);

create table public.booking_series (
  id uuid primary key default gen_random_uuid(),
  parent_id uuid not null references public.parents (id) on delete cascade,
  instructor_id uuid references public.instructors (id) on delete set null,
  zone_id uuid not null references public.zones (id),
  weekday smallint not null check (weekday between 0 and 6),
  start_time time not null,                                     -- local wall clock
  duration_minutes integer not null check (duration_minutes > 0),
  children_count integer not null check (children_count > 0),
  starts_on date not null,
  ends_on date,
  discount_pct numeric(5,2) not null default 0,
  status public.series_status not null default 'pending_payment',
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  check (ends_on is null or ends_on >= starts_on)
);

create index booking_series_parent_idx on public.booking_series (parent_id);
create index booking_series_instructor_idx on public.booking_series (instructor_id);

-- -----------------------------------------------------------------------------
-- Bookings
-- -----------------------------------------------------------------------------
create table public.bookings (
  id uuid primary key default gen_random_uuid(),
  parent_id uuid not null references public.parents (id) on delete restrict,
  instructor_id uuid references public.instructors (id) on delete restrict,
  requested_instructor_id uuid references public.instructors (id) on delete set null, -- null = first available
  zone_id uuid not null references public.zones (id),
  neighborhood text,                                            -- coarse; safe for instructors
  starts_at timestamptz not null,
  ends_at timestamptz not null,
  duration_minutes integer generated always as ((extract(epoch from (ends_at - starts_at)) / 60)::integer) stored,
  status public.booking_status not null default 'pending_payment',
  kind public.booking_kind not null default 'single',
  series_id uuid references public.booking_series (id) on delete set null,
  package_id uuid references public.packages (id) on delete set null,
  children_count integer not null default 1 check (children_count > 0),
  is_neighborhood_slot boolean not null default false,
  hold_expires_at timestamptz,                                  -- for pending_payment
  source text not null default 'web',                           -- web | admin | import:<adapter>
  external_ref text,
  created_by uuid references public.users (id) on delete set null,
  confirmed_at timestamptz,
  completed_at timestamptz,
  cancelled_at timestamptz,
  cancelled_by uuid references public.users (id) on delete set null,
  cancellation_reason text,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  check (ends_at > starts_at),
  check (ends_at - starts_at <= interval '4 hours'),
  -- Hard guarantee against double booking: no two live bookings for the same
  -- instructor may overlap in time. Travel buffers are enforced by the
  -- scheduling engine inside the booking transaction (Phase 2).
  constraint bookings_no_instructor_overlap exclude using gist (
    instructor_id with =,
    tstzrange(starts_at, ends_at, '[)') with &&
  ) where (
    instructor_id is not null
    and status in ('pending_payment', 'pending_instructor', 'confirmed', 'completed')
  )
);

create index bookings_parent_idx on public.bookings (parent_id, starts_at desc);
create index bookings_instructor_idx on public.bookings (instructor_id, starts_at);
create index bookings_zone_time_idx on public.bookings (zone_id, starts_at);
create index bookings_status_idx on public.bookings (status);
create index bookings_series_idx on public.bookings (series_id);

create table public.booking_children (
  booking_id uuid not null references public.bookings (id) on delete cascade,
  child_id uuid not null references public.children (id) on delete restrict,
  primary key (booking_id, child_id)
);

create index booking_children_child_idx on public.booking_children (child_id);

-- The street address for a specific lesson. Instructors have NO direct access.
create table public.booking_locations (
  booking_id uuid primary key references public.bookings (id) on delete cascade,
  address_line1 text not null,
  address_line2 text,
  city text not null,
  state text not null default 'CA',
  postal_code text not null,
  lat double precision,
  lng double precision,
  google_place_id text,
  access_notes text,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

-- What the parent paid. Instructors have NO access.
create table public.booking_pricing (
  booking_id uuid primary key references public.bookings (id) on delete cascade,
  currency text not null default 'usd',
  base_cents integer not null default 0,
  extra_children_cents integer not null default 0,
  travel_fee_cents integer not null default 0,
  neighborhood_discount_cents integer not null default 0,
  package_discount_cents integer not null default 0,
  series_discount_cents integer not null default 0,
  promo_discount_cents integer not null default 0,
  discount_code_id uuid,
  total_cents integer not null check (total_cents >= 0),
  snapshot jsonb not null default '{}'::jsonb,                  -- pricing_config at time of booking
  created_at timestamptz not null default now()
);

-- Booking request → instructor accept/decline, with auto-offer to next match.
create table public.booking_offers (
  id uuid primary key default gen_random_uuid(),
  booking_id uuid not null references public.bookings (id) on delete cascade,
  instructor_id uuid not null references public.instructors (id) on delete cascade,
  rank integer not null default 1,
  status public.offer_status not null default 'pending',
  -- Non-identifying summary shown before acceptance: ages, levels, zone, time.
  lesson_summary jsonb not null default '{}'::jsonb,
  offered_at timestamptz not null default now(),
  expires_at timestamptz not null,
  responded_at timestamptz,
  decline_reason text,
  unique (booking_id, instructor_id)
);

create index booking_offers_instructor_idx on public.booking_offers (instructor_id, status);
create unique index booking_offers_one_pending on public.booking_offers (booking_id) where status = 'pending';

create table public.lesson_notes (
  id uuid primary key default gen_random_uuid(),
  booking_id uuid not null unique references public.bookings (id) on delete cascade,
  instructor_id uuid not null references public.instructors (id) on delete restrict,
  skills jsonb not null default '{}'::jsonb,                    -- {"floating": "mastered", ...}
  summary text,
  next_focus text,
  is_flagged boolean not null default false,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create table public.open_shifts (
  id uuid primary key default gen_random_uuid(),
  booking_id uuid not null references public.bookings (id) on delete cascade,
  released_by uuid not null references public.instructors (id) on delete cascade,
  reason text,
  status public.open_shift_status not null default 'open',
  -- Denormalized, non-identifying details so claimers never need booking access.
  zone_id uuid not null references public.zones (id),
  neighborhood text,
  starts_at timestamptz not null,
  ends_at timestamptz not null,
  lesson_summary jsonb not null default '{}'::jsonb,            -- ages + levels only
  claimed_by uuid references public.instructors (id) on delete set null,
  claimed_at timestamptz,
  decided_by uuid references public.users (id) on delete set null,
  decided_at timestamptz,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create unique index open_shifts_one_active_per_booking
  on public.open_shifts (booking_id) where status in ('open', 'pending_approval');
create index open_shifts_status_zone_idx on public.open_shifts (status, zone_id, starts_at);

-- -----------------------------------------------------------------------------
-- Money
-- -----------------------------------------------------------------------------
create table public.discount_codes (
  id uuid primary key default gen_random_uuid(),
  code text not null,
  description text,
  percent_off numeric(5,2) check (percent_off > 0 and percent_off <= 100),
  amount_off_cents integer check (amount_off_cents > 0),
  applies_to public.booking_kind[] not null default '{single,package,recurring}',
  max_redemptions integer check (max_redemptions > 0),
  redemptions integer not null default 0,
  valid_from timestamptz,
  valid_until timestamptz,
  is_active boolean not null default true,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  check ((percent_off is null) <> (amount_off_cents is null))
);

create unique index discount_codes_code_idx on public.discount_codes (upper(code));

alter table public.booking_pricing
  add constraint booking_pricing_discount_code_fk
  foreign key (discount_code_id) references public.discount_codes (id) on delete set null;

create table public.payments (
  id uuid primary key default gen_random_uuid(),
  parent_id uuid references public.parents (id) on delete set null,
  booking_id uuid references public.bookings (id) on delete set null,
  package_id uuid references public.packages (id) on delete set null,
  series_id uuid references public.booking_series (id) on delete set null,
  day_pass_inquiry_id uuid,
  amount_cents integer not null check (amount_cents >= 0),
  refunded_cents integer not null default 0 check (refunded_cents >= 0),
  currency text not null default 'usd',
  status public.payment_status not null default 'pending',
  description text,
  stripe_checkout_session_id text unique,
  stripe_payment_intent_id text unique,
  stripe_charge_id text,
  receipt_url text,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  check (refunded_cents <= amount_cents)
);

create index payments_parent_idx on public.payments (parent_id, created_at desc);
create index payments_booking_idx on public.payments (booking_id);

create table public.instructor_payouts (
  id uuid primary key default gen_random_uuid(),
  instructor_id uuid not null references public.instructors (id) on delete restrict,
  amount_cents integer not null check (amount_cents >= 0),
  period_start date not null,
  period_end date not null,
  paid_at timestamptz,
  method text,                                     -- direct_deposit | check | stripe_connect
  reference text,
  created_at timestamptz not null default now(),
  check (period_end >= period_start)
);

create index instructor_payouts_instructor_idx on public.instructor_payouts (instructor_id, period_end desc);

create table public.instructor_earnings (
  id uuid primary key default gen_random_uuid(),
  instructor_id uuid not null references public.instructors (id) on delete restrict,
  booking_id uuid not null references public.bookings (id) on delete restrict,
  minutes integer not null check (minutes > 0),
  rate_cents_per_hour integer not null check (rate_cents_per_hour >= 0),
  amount_cents integer not null check (amount_cents >= 0),
  status public.earning_status not null default 'pending',
  earned_on date not null,                          -- local lesson date
  payout_id uuid references public.instructor_payouts (id) on delete set null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (instructor_id, booking_id)
);

create index instructor_earnings_instructor_idx on public.instructor_earnings (instructor_id, earned_on desc);

-- -----------------------------------------------------------------------------
-- Messaging & moderation
-- -----------------------------------------------------------------------------
create table public.messages (
  id uuid primary key default gen_random_uuid(),
  booking_id uuid not null references public.bookings (id) on delete cascade,
  sender_id uuid not null default auth.uid() references public.users (id) on delete cascade,
  sender_role public.user_role not null default 'parent',   -- overwritten by trigger
  body text not null check (length(body) between 1 and 2000), -- post-filter (redacted) text
  is_flagged boolean not null default false,
  read_at timestamptz,
  created_at timestamptz not null default now()
);

create index messages_booking_idx on public.messages (booking_id, created_at);

create table public.flagged_messages (
  id uuid primary key default gen_random_uuid(),
  source text not null check (source in ('message', 'lesson_note', 'profile', 'sms')),
  message_id uuid references public.messages (id) on delete set null,
  lesson_note_id uuid references public.lesson_notes (id) on delete set null,
  booking_id uuid references public.bookings (id) on delete set null,
  sender_id uuid references public.users (id) on delete set null,
  sender_role public.user_role,
  original_body text not null,                     -- admin-only; never shown to the recipient
  redacted_body text,
  reasons public.flag_reason[] not null,
  matches text[] not null default '{}',
  status public.flag_status not null default 'open',
  reviewed_by uuid references public.users (id) on delete set null,
  reviewed_at timestamptz,
  admin_notes text,
  created_at timestamptz not null default now()
);

create index flagged_messages_status_idx on public.flagged_messages (status, created_at desc);
create index flagged_messages_sender_idx on public.flagged_messages (sender_id);

-- -----------------------------------------------------------------------------
-- Audit log (append-only)
-- -----------------------------------------------------------------------------
create table public.audit_log (
  id bigint generated always as identity primary key,
  occurred_at timestamptz not null default now(),
  actor_id uuid,
  actor_role public.user_role,
  action text not null,                            -- e.g. instructor.view_lesson
  entity_type text,
  entity_id uuid,
  booking_id uuid,
  metadata jsonb not null default '{}'::jsonb,
  ip_address text,
  user_agent text
);

create index audit_log_actor_idx on public.audit_log (actor_id, occurred_at desc);
create index audit_log_action_idx on public.audit_log (action, occurred_at desc);
create index audit_log_booking_idx on public.audit_log (booking_id);

create or replace function private.audit_log_immutable()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  raise exception 'audit_log is append-only' using errcode = '42501';
end;
$$;

create trigger audit_log_no_update
  before update or delete on public.audit_log
  for each row execute function private.audit_log_immutable();

-- -----------------------------------------------------------------------------
-- Partner Club Day Pass inquiries (inquiry only — never instant-booked)
-- -----------------------------------------------------------------------------
create table public.day_pass_inquiries (
  id uuid primary key default gen_random_uuid(),
  parent_id uuid references public.parents (id) on delete set null,
  contact_name text not null,
  contact_email text not null,
  contact_phone text,
  adults_count integer not null default 2 check (adults_count between 0 and 20),
  children_count integer not null default 0 check (children_count between 0 and 20),
  preferred_dates date[] not null default '{}',
  interest_level public.interest_level not null default 'interested',
  message text,
  status public.inquiry_status not null default 'new',
  quoted_amount_cents integer check (quoted_amount_cents >= 0),
  stripe_payment_link_url text,
  admin_notes text,
  handled_by uuid references public.users (id) on delete set null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create index day_pass_inquiries_status_idx on public.day_pass_inquiries (status, created_at desc);

alter table public.payments
  add constraint payments_day_pass_fk
  foreign key (day_pass_inquiry_id) references public.day_pass_inquiries (id) on delete set null;

-- -----------------------------------------------------------------------------
-- Outbound webhooks
-- -----------------------------------------------------------------------------
create table public.webhooks (
  id uuid primary key default gen_random_uuid(),
  url text not null check (url ~ '^https://'),
  description text,
  signing_secret text not null default private.random_token(),
  events text[] not null check (events <@ array['booking.created', 'booking.cancelled', 'lesson.completed']::text[]),
  is_active boolean not null default true,
  created_by uuid references public.users (id) on delete set null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create table public.webhook_deliveries (
  id uuid primary key default gen_random_uuid(),
  webhook_id uuid not null references public.webhooks (id) on delete cascade,
  event text not null,
  event_id uuid not null default gen_random_uuid(),
  payload jsonb not null,
  status text not null default 'pending' check (status in ('pending', 'succeeded', 'failed', 'dead')),
  attempts integer not null default 0,
  next_attempt_at timestamptz not null default now(),
  last_attempt_at timestamptz,
  response_status integer,
  response_body text,
  created_at timestamptz not null default now()
);

create index webhook_deliveries_pending_idx on public.webhook_deliveries (next_attempt_at) where status = 'pending';

-- -----------------------------------------------------------------------------
-- updated_at triggers
-- -----------------------------------------------------------------------------
do $$
declare
  t text;
begin
  foreach t in array array[
    'platform_settings', 'pricing_config', 'lesson_prices', 'package_offerings', 'zones',
    'users', 'instructors', 'instructor_private', 'instructor_certifications', 'parents',
    'children', 'availability_rules', 'availability_overrides', 'packages', 'booking_series',
    'bookings', 'booking_locations', 'lesson_notes', 'open_shifts', 'discount_codes',
    'payments', 'instructor_earnings', 'day_pass_inquiries', 'webhooks'
  ]
  loop
    execute format(
      'create trigger %I before update on public.%I for each row execute function private.set_updated_at()',
      t || '_set_updated_at', t
    );
  end loop;
end $$;

-- Singletons
insert into public.platform_settings default values on conflict do nothing;
insert into public.pricing_config default values on conflict do nothing;

-- ===== 20261013000300_rls.sql =====
-- =============================================================================
-- Phase 1 · Row-Level Security
--
-- Two layers, both enforced by Postgres:
--   1. GRANTS decide which tables/columns the `anon` and `authenticated` API
--      roles can touch at all. We revoke Supabase's permissive defaults and
--      grant explicitly, so a new table is invisible until someone grants it.
--   2. RLS POLICIES decide which rows each user sees.
--
-- Privileged writes (pricing, role changes, refunds, booking creation) are done
-- server-side with the service role after an explicit admin/ownership check,
-- and are written to audit_log. The API roles cannot perform them directly.
-- =============================================================================

-- -----------------------------------------------------------------------------
-- 0. Lock down defaults
-- -----------------------------------------------------------------------------
revoke all on all tables in schema public from anon, authenticated;
revoke all on all sequences in schema public from anon, authenticated;
revoke all on all functions in schema public from public, anon, authenticated;
revoke all on all functions in schema private from public, anon, authenticated;

alter default privileges in schema public revoke all on tables from anon, authenticated;
alter default privileges in schema public revoke all on sequences from anon, authenticated;
alter default privileges in schema public revoke execute on functions from public, anon, authenticated;
alter default privileges in schema private revoke execute on functions from public, anon, authenticated;

grant usage on schema public to anon, authenticated, service_role;
grant all on all tables in schema public to service_role;
grant all on all sequences in schema public to service_role;
alter default privileges in schema public grant all on tables to service_role;
alter default privileges in schema public grant all on sequences to service_role;

-- -----------------------------------------------------------------------------
-- 1. Helper functions (SECURITY DEFINER: they read tables the caller may not
--    see; they bypass RLS as the table owner, so there is no policy recursion)
-- -----------------------------------------------------------------------------
create or replace function private.caller_role()
returns public.user_role
language sql
stable
security definer
set search_path = ''
as $$
  select u.role from public.users u where u.id = (select auth.uid())
$$;

create or replace function private.is_admin()
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select coalesce(private.caller_role() = 'admin', false)
$$;

create or replace function private.has_accepted_current_terms(p_instructor_id uuid)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select exists (
    select 1
    from public.instructor_terms_acceptances a
    join public.platform_settings s on s.instructor_terms_version = a.terms_version
    where a.instructor_id = p_instructor_id
  )
$$;

-- An instructor may see client-related rows only while: their role is
-- instructor, admin has activated them, and they accepted the CURRENT terms.
-- Bumping platform_settings.instructor_terms_version cuts off access until
-- each instructor re-accepts.
create or replace function private.is_active_instructor()
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select exists (
    select 1
    from public.users u
    join public.instructors i on i.id = u.id
    where u.id = (select auth.uid())
      and u.role = 'instructor'
      and i.is_active
  ) and private.has_accepted_current_terms((select auth.uid()))
$$;

create or replace function private.is_booking_parent(p_booking_id uuid)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select exists (
    select 1 from public.bookings b
    where b.id = p_booking_id and b.parent_id = (select auth.uid())
  )
$$;

create or replace function private.is_booking_instructor(p_booking_id uuid)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select private.is_active_instructor() and exists (
    select 1 from public.bookings b
    where b.id = p_booking_id and b.instructor_id = (select auth.uid())
  )
$$;

create or replace function private.parent_has_booked_instructor(p_instructor_id uuid)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select exists (
    select 1 from public.bookings b
    where b.instructor_id = p_instructor_id and b.parent_id = (select auth.uid())
  )
$$;

create or replace function private.instructor_covers_zone(p_zone_id uuid)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select exists (
    select 1 from public.instructor_zones z
    where z.zone_id = p_zone_id and z.instructor_id = (select auth.uid())
  )
$$;

grant execute on all functions in schema private to anon, authenticated, service_role;

-- -----------------------------------------------------------------------------
-- 2. Enable RLS on every table in public
-- -----------------------------------------------------------------------------
do $$
declare
  t record;
begin
  for t in select tablename from pg_tables where schemaname = 'public'
  loop
    execute format('alter table public.%I enable row level security', t.tablename);
  end loop;
end $$;

-- -----------------------------------------------------------------------------
-- 3. Public configuration (readable by everyone, incl. logged-out visitors)
-- -----------------------------------------------------------------------------
grant select on public.platform_settings, public.pricing_config, public.lesson_prices,
  public.package_offerings, public.zones to anon, authenticated;

create policy platform_settings_read on public.platform_settings for select to anon, authenticated using (true);
create policy pricing_config_read on public.pricing_config for select to anon, authenticated using (true);
create policy lesson_prices_read on public.lesson_prices for select to anon, authenticated using (is_active or (select private.is_admin()));
create policy package_offerings_read on public.package_offerings for select to anon, authenticated using (is_active or (select private.is_admin()));
create policy zones_read on public.zones for select to anon, authenticated using (true);

grant select on public.zone_travel_buffers to authenticated;
create policy zone_travel_buffers_read on public.zone_travel_buffers for select to authenticated
  using ((select private.is_admin()) or (select private.is_active_instructor()));

-- -----------------------------------------------------------------------------
-- 4. users — contact details. Self + admin ONLY. Never instructors.
-- -----------------------------------------------------------------------------
grant select on public.users to authenticated;
-- role / email are NOT updatable through the API (role changes are admin
-- server actions; email follows auth.users).
grant update (first_name, last_name, phone, sms_opt_in, email_opt_in, onboarded_at) on public.users to authenticated;

create policy users_select_self on public.users for select to authenticated
  using (id = (select auth.uid()));
create policy users_select_admin on public.users for select to authenticated
  using ((select private.is_admin()));
create policy users_update_self on public.users for update to authenticated
  using (id = (select auth.uid())) with check (id = (select auth.uid()));

-- -----------------------------------------------------------------------------
-- 5. parents — home address, Stripe id. Self + admin ONLY.
-- -----------------------------------------------------------------------------
grant select on public.parents to authenticated;
-- Address/zone are set by a server action that validates the zone; parents
-- may only change preferences directly.
grant update (favorite_instructor_id, preferred_days, preferred_time_windows) on public.parents to authenticated;

create policy parents_select_self on public.parents for select to authenticated
  using (id = (select auth.uid()));
create policy parents_select_admin on public.parents for select to authenticated
  using ((select private.is_admin()));
create policy parents_update_self on public.parents for update to authenticated
  using (id = (select auth.uid())) with check (id = (select auth.uid()));

-- -----------------------------------------------------------------------------
-- 6. children — parent + admin. Instructors read ONLY via the audited RPCs in
--    the next migration (instructor_lessons / instructor_lesson).
-- -----------------------------------------------------------------------------
grant select, delete on public.children to authenticated;
grant insert (parent_id, first_name, birth_date, swim_level, notes) on public.children to authenticated;
grant update (first_name, birth_date, swim_level, notes, is_active) on public.children to authenticated;

create policy children_select_parent on public.children for select to authenticated
  using (parent_id = (select auth.uid()));
create policy children_select_admin on public.children for select to authenticated
  using ((select private.is_admin()));
create policy children_insert_parent on public.children for insert to authenticated
  with check (parent_id = (select auth.uid()));
create policy children_update_parent on public.children for update to authenticated
  using (parent_id = (select auth.uid())) with check (parent_id = (select auth.uid()));
create policy children_delete_parent on public.children for delete to authenticated
  using (parent_id = (select auth.uid()));

-- -----------------------------------------------------------------------------
-- 7. Instructors (public profile), private profile, certifications, zones
-- -----------------------------------------------------------------------------
grant select on public.instructors to anon, authenticated;
-- display_name is admin-controlled (first name + last initial) so it can't be
-- used to smuggle contact details to parents. Free-text bio is screened by the
-- Phase 4 contact filter.
grant update (bio, photo_path, specialties, levels_taught, min_child_age_months,
  max_children_per_lesson, years_experience, languages, is_accepting_new_clients)
  on public.instructors to authenticated;

create policy instructors_select_public on public.instructors for select to anon, authenticated
  using (is_active);
create policy instructors_select_self on public.instructors for select to authenticated
  using (id = (select auth.uid()));
create policy instructors_select_booked on public.instructors for select to authenticated
  using ((select private.parent_has_booked_instructor(id)));
create policy instructors_select_admin on public.instructors for select to authenticated
  using ((select private.is_admin()));
create policy instructors_update_self on public.instructors for update to authenticated
  using (id = (select auth.uid())) with check (id = (select auth.uid()));

-- Pay rate + iCal token: self + admin. Nobody can change their own pay rate.
grant select on public.instructor_private to authenticated;
create policy instructor_private_select_self on public.instructor_private for select to authenticated
  using (instructor_id = (select auth.uid()));
create policy instructor_private_select_admin on public.instructor_private for select to authenticated
  using ((select private.is_admin()));

grant select on public.instructor_terms_acceptances to authenticated;
create policy terms_select_self on public.instructor_terms_acceptances for select to authenticated
  using (instructor_id = (select auth.uid()));
create policy terms_select_admin on public.instructor_terms_acceptances for select to authenticated
  using ((select private.is_admin()));

grant select on public.instructor_invites to authenticated;
create policy invites_select_admin on public.instructor_invites for select to authenticated
  using ((select private.is_admin()));

-- Certifications: the public sees verified, unexpired certs (trust badges).
grant select on public.instructor_certifications to anon, authenticated;
grant insert (instructor_id, kind, issuer, issued_on, expires_on, document_path) on public.instructor_certifications to authenticated;
grant delete on public.instructor_certifications to authenticated;

create policy certs_select_public on public.instructor_certifications for select to anon, authenticated
  using (verified_at is not null and (expires_on is null or expires_on >= private.la_date(now())));
create policy certs_select_self on public.instructor_certifications for select to authenticated
  using (instructor_id = (select auth.uid()));
create policy certs_select_admin on public.instructor_certifications for select to authenticated
  using ((select private.is_admin()));
create policy certs_insert_self on public.instructor_certifications for insert to authenticated
  with check (instructor_id = (select auth.uid()) and (select private.caller_role()) = 'instructor');
-- Instructors may remove only their own *unverified* uploads.
create policy certs_delete_self on public.instructor_certifications for delete to authenticated
  using (instructor_id = (select auth.uid()) and verified_at is null);

grant select, insert, delete on public.instructor_zones to authenticated;
create policy instructor_zones_select_self on public.instructor_zones for select to authenticated
  using (instructor_id = (select auth.uid()));
create policy instructor_zones_select_admin on public.instructor_zones for select to authenticated
  using ((select private.is_admin()));
create policy instructor_zones_insert_self on public.instructor_zones for insert to authenticated
  with check (instructor_id = (select auth.uid()) and (select private.caller_role()) = 'instructor');
create policy instructor_zones_delete_self on public.instructor_zones for delete to authenticated
  using (instructor_id = (select auth.uid()));

-- -----------------------------------------------------------------------------
-- 8. Availability — instructor owns their own; admin reads all.
-- -----------------------------------------------------------------------------
grant select, delete on public.availability_rules, public.availability_overrides to authenticated;
grant insert (instructor_id, weekday, start_time, end_time, effective_from, effective_until),
  update (weekday, start_time, end_time, effective_from, effective_until)
  on public.availability_rules to authenticated;
grant insert (instructor_id, date, kind, start_time, end_time, note),
  update (date, kind, start_time, end_time, note)
  on public.availability_overrides to authenticated;

create policy availability_rules_select on public.availability_rules for select to authenticated
  using (instructor_id = (select auth.uid()) or (select private.is_admin()));
create policy availability_rules_insert on public.availability_rules for insert to authenticated
  with check (instructor_id = (select auth.uid()) and (select private.caller_role()) = 'instructor');
create policy availability_rules_update on public.availability_rules for update to authenticated
  using (instructor_id = (select auth.uid())) with check (instructor_id = (select auth.uid()));
create policy availability_rules_delete on public.availability_rules for delete to authenticated
  using (instructor_id = (select auth.uid()));

create policy availability_overrides_select on public.availability_overrides for select to authenticated
  using (instructor_id = (select auth.uid()) or (select private.is_admin()));
create policy availability_overrides_insert on public.availability_overrides for insert to authenticated
  with check (instructor_id = (select auth.uid()) and (select private.caller_role()) = 'instructor');
create policy availability_overrides_update on public.availability_overrides for update to authenticated
  using (instructor_id = (select auth.uid())) with check (instructor_id = (select auth.uid()));
create policy availability_overrides_delete on public.availability_overrides for delete to authenticated
  using (instructor_id = (select auth.uid()));

-- -----------------------------------------------------------------------------
-- 9. Bookings. The bookings row itself carries no PII and no prices, so the
--    assigned (active, terms-accepted) instructor may read it directly.
--    All writes go through server actions (pricing + Stripe must be enforced).
-- -----------------------------------------------------------------------------
grant select on public.bookings to authenticated;

create policy bookings_select_parent on public.bookings for select to authenticated
  using (parent_id = (select auth.uid()));
create policy bookings_select_instructor on public.bookings for select to authenticated
  using (instructor_id = (select auth.uid()) and (select private.is_active_instructor()));
create policy bookings_select_admin on public.bookings for select to authenticated
  using ((select private.is_admin()));

grant select on public.booking_children, public.booking_locations, public.booking_pricing to authenticated;

create policy booking_children_select_parent on public.booking_children for select to authenticated
  using ((select private.is_booking_parent(booking_id)));
create policy booking_children_select_admin on public.booking_children for select to authenticated
  using ((select private.is_admin()));

-- NOTE: deliberately no instructor policy. See instructor_lesson(s) RPCs.
create policy booking_locations_select_parent on public.booking_locations for select to authenticated
  using ((select private.is_booking_parent(booking_id)));
create policy booking_locations_select_admin on public.booking_locations for select to authenticated
  using ((select private.is_admin()));

create policy booking_pricing_select_parent on public.booking_pricing for select to authenticated
  using ((select private.is_booking_parent(booking_id)));
create policy booking_pricing_select_admin on public.booking_pricing for select to authenticated
  using ((select private.is_admin()));

grant select on public.booking_offers to authenticated;
create policy booking_offers_select_self on public.booking_offers for select to authenticated
  using (instructor_id = (select auth.uid()) and (select private.is_active_instructor()));
create policy booking_offers_select_admin on public.booking_offers for select to authenticated
  using ((select private.is_admin()));

grant select on public.booking_series to authenticated;
create policy booking_series_select_parent on public.booking_series for select to authenticated
  using (parent_id = (select auth.uid()));
create policy booking_series_select_instructor on public.booking_series for select to authenticated
  using (instructor_id = (select auth.uid()) and (select private.is_active_instructor()));
create policy booking_series_select_admin on public.booking_series for select to authenticated
  using ((select private.is_admin()));

grant select on public.packages to authenticated;
create policy packages_select_parent on public.packages for select to authenticated
  using (parent_id = (select auth.uid()));
create policy packages_select_admin on public.packages for select to authenticated
  using ((select private.is_admin()));

-- -----------------------------------------------------------------------------
-- 10. Lesson notes — written by the assigned instructor, read by the parent.
-- -----------------------------------------------------------------------------
grant select on public.lesson_notes to authenticated;
grant insert (booking_id, instructor_id, skills, summary, next_focus) on public.lesson_notes to authenticated;
grant update (skills, summary, next_focus) on public.lesson_notes to authenticated;

create policy lesson_notes_select_parent on public.lesson_notes for select to authenticated
  using ((select private.is_booking_parent(booking_id)));
create policy lesson_notes_select_instructor on public.lesson_notes for select to authenticated
  using (instructor_id = (select auth.uid()) and (select private.is_booking_instructor(booking_id)));
create policy lesson_notes_select_admin on public.lesson_notes for select to authenticated
  using ((select private.is_admin()));
create policy lesson_notes_insert_instructor on public.lesson_notes for insert to authenticated
  with check (instructor_id = (select auth.uid()) and (select private.is_booking_instructor(booking_id)));
create policy lesson_notes_update_instructor on public.lesson_notes for update to authenticated
  using (instructor_id = (select auth.uid()) and (select private.is_booking_instructor(booking_id)))
  with check (instructor_id = (select auth.uid()));

-- -----------------------------------------------------------------------------
-- 11. Open shifts (sub board). Carries only zone/time/ages/levels.
-- -----------------------------------------------------------------------------
grant select on public.open_shifts to authenticated;
create policy open_shifts_select_board on public.open_shifts for select to authenticated
  using (
    status = 'open'
    and released_by <> (select auth.uid())
    and (select private.is_active_instructor())
    and (select private.instructor_covers_zone(zone_id))
  );
create policy open_shifts_select_involved on public.open_shifts for select to authenticated
  using ((released_by = (select auth.uid()) or claimed_by = (select auth.uid())) and (select private.is_active_instructor()));
create policy open_shifts_select_admin on public.open_shifts for select to authenticated
  using ((select private.is_admin()));

-- -----------------------------------------------------------------------------
-- 12. Money. Parents see their own payments; instructors see only their own
--     earnings/payouts (pay rate × minutes) — never what the parent paid.
-- -----------------------------------------------------------------------------
grant select on public.payments to authenticated;
create policy payments_select_parent on public.payments for select to authenticated
  using (parent_id = (select auth.uid()));
create policy payments_select_admin on public.payments for select to authenticated
  using ((select private.is_admin()));

grant select on public.instructor_earnings, public.instructor_payouts to authenticated;
create policy earnings_select_self on public.instructor_earnings for select to authenticated
  using (instructor_id = (select auth.uid()));
create policy earnings_select_admin on public.instructor_earnings for select to authenticated
  using ((select private.is_admin()));
create policy payouts_select_self on public.instructor_payouts for select to authenticated
  using (instructor_id = (select auth.uid()));
create policy payouts_select_admin on public.instructor_payouts for select to authenticated
  using ((select private.is_admin()));

grant select on public.discount_codes to authenticated;
create policy discount_codes_select_admin on public.discount_codes for select to authenticated
  using ((select private.is_admin()));

-- -----------------------------------------------------------------------------
-- 13. Messages — the booking's parent and its assigned instructor.
--     (Phase 4 adds the BEFORE INSERT contact-info filter trigger.)
-- -----------------------------------------------------------------------------
grant select on public.messages to authenticated;
grant insert (booking_id, body) on public.messages to authenticated;
grant update (read_at) on public.messages to authenticated;

create policy messages_select_participant on public.messages for select to authenticated
  using ((select private.is_booking_parent(booking_id)) or (select private.is_booking_instructor(booking_id)));
create policy messages_select_admin on public.messages for select to authenticated
  using ((select private.is_admin()));
create policy messages_insert_participant on public.messages for insert to authenticated
  with check (
    sender_id = (select auth.uid())
    and ((select private.is_booking_parent(booking_id)) or (select private.is_booking_instructor(booking_id)))
  );
-- Recipients mark messages read; they cannot edit bodies (column grant).
create policy messages_update_recipient on public.messages for update to authenticated
  using (
    sender_id <> (select auth.uid())
    and ((select private.is_booking_parent(booking_id)) or (select private.is_booking_instructor(booking_id)))
  );

grant select, update (status, reviewed_by, reviewed_at, admin_notes) on public.flagged_messages to authenticated;
create policy flagged_messages_admin_select on public.flagged_messages for select to authenticated
  using ((select private.is_admin()));
create policy flagged_messages_admin_update on public.flagged_messages for update to authenticated
  using ((select private.is_admin())) with check ((select private.is_admin()));

-- -----------------------------------------------------------------------------
-- 14. Audit log — admin read only. Nobody inserts directly through the API;
--     rows are written by SECURITY DEFINER functions and server actions.
-- -----------------------------------------------------------------------------
grant select on public.audit_log to authenticated;
create policy audit_log_admin_select on public.audit_log for select to authenticated
  using ((select private.is_admin()));

-- -----------------------------------------------------------------------------
-- 15. Day pass inquiries — submitted through a rate-limited server action.
-- -----------------------------------------------------------------------------
grant select on public.day_pass_inquiries to authenticated;
grant update (status, quoted_amount_cents, stripe_payment_link_url, admin_notes, handled_by) on public.day_pass_inquiries to authenticated;
create policy day_pass_select_own on public.day_pass_inquiries for select to authenticated
  using (parent_id = (select auth.uid()));
create policy day_pass_select_admin on public.day_pass_inquiries for select to authenticated
  using ((select private.is_admin()));
create policy day_pass_update_admin on public.day_pass_inquiries for update to authenticated
  using ((select private.is_admin())) with check ((select private.is_admin()));

-- -----------------------------------------------------------------------------
-- 16. Webhooks — admin only (secrets never leave the server otherwise).
-- -----------------------------------------------------------------------------
grant select on public.webhooks, public.webhook_deliveries to authenticated;
create policy webhooks_admin_select on public.webhooks for select to authenticated
  using ((select private.is_admin()));
create policy webhook_deliveries_admin_select on public.webhook_deliveries for select to authenticated
  using ((select private.is_admin()));

-- ===== 20261013000400_auth_and_instructor_access.sql =====
-- =============================================================================
-- Phase 1 · Auth hooks, terms acceptance, and the audited instructor read path
-- =============================================================================

-- -----------------------------------------------------------------------------
-- Request context helpers (PostgREST exposes request headers as a GUC)
-- -----------------------------------------------------------------------------
create or replace function private.request_header(p_name text)
returns text
language plpgsql
stable
set search_path = ''
as $$
declare
  v_raw text := current_setting('request.headers', true);
begin
  if v_raw is null or v_raw = '' then
    return null;
  end if;
  return (v_raw::json ->> lower(p_name));
exception when others then
  return null;
end;
$$;

create or replace function private.write_audit(
  p_action text,
  p_entity_type text,
  p_entity_id uuid,
  p_booking_id uuid default null,
  p_metadata jsonb default '{}'::jsonb
)
returns void
language sql
security definer
set search_path = ''
as $$
  insert into public.audit_log (actor_id, actor_role, action, entity_type, entity_id, booking_id, metadata, ip_address, user_agent)
  values (
    (select auth.uid()),
    private.caller_role(),
    p_action,
    p_entity_type,
    p_entity_id,
    p_booking_id,
    coalesce(p_metadata, '{}'::jsonb),
    split_part(coalesce(private.request_header('x-forwarded-for'), ''), ',', 1),
    left(private.request_header('user-agent'), 400)
  )
$$;

-- -----------------------------------------------------------------------------
-- New auth user → public.users (+ parents | instructors)
--
-- Role resolution (raw_user_meta_data is user-controlled and is NEVER trusted
-- for roles):
--   1. a pending, unexpired instructor_invites row for the email → instructor
--   2. raw_app_meta_data.role (only settable with the service role) → as given
--   3. otherwise → parent
-- -----------------------------------------------------------------------------
create or replace function private.handle_new_auth_user()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_role public.user_role := 'parent';
  v_invite public.instructor_invites;
  v_meta jsonb := coalesce(new.raw_user_meta_data, '{}'::jsonb);
  v_full_name text := nullif(trim(coalesce(v_meta ->> 'full_name', v_meta ->> 'name', '')), '');
  v_first text := nullif(trim(coalesce(v_meta ->> 'first_name', v_meta ->> 'given_name', '')), '');
  v_last text := nullif(trim(coalesce(v_meta ->> 'last_name', v_meta ->> 'family_name', '')), '');
  v_default_rate integer;
begin
  select * into v_invite
  from public.instructor_invites i
  where lower(i.email) = lower(new.email)
    and i.accepted_at is null
    and i.expires_at > now()
  order by i.created_at desc
  limit 1;

  if found then
    v_role := 'instructor';
  elsif (new.raw_app_meta_data ->> 'role') in ('instructor', 'admin') then
    v_role := (new.raw_app_meta_data ->> 'role')::public.user_role;
  end if;

  if v_first is null and v_full_name is not null then
    v_first := split_part(v_full_name, ' ', 1);
    v_last := coalesce(v_last, nullif(trim(substr(v_full_name, length(v_first) + 1)), ''));
  end if;

  insert into public.users (id, role, email, first_name, last_name)
  values (new.id, v_role, coalesce(new.email, ''), v_first, v_last)
  on conflict (id) do nothing;

  if v_role = 'parent' then
    insert into public.parents (id) values (new.id) on conflict (id) do nothing;
  elsif v_role = 'instructor' then
    select default_instructor_pay_cents_per_hour into v_default_rate from public.platform_settings;

    insert into public.instructors (id, display_name, is_active)
    values (
      new.id,
      coalesce(v_first, 'Instructor') || coalesce(' ' || left(v_last, 1) || '.', ''),
      false
    )
    on conflict (id) do nothing;

    insert into public.instructor_private (instructor_id, pay_rate_cents_per_hour)
    values (new.id, coalesce(v_invite.pay_rate_cents_per_hour, v_default_rate, 4000))
    on conflict (instructor_id) do nothing;

    if v_invite.id is not null then
      update public.instructor_invites
      set accepted_at = now(), accepted_user_id = new.id
      where id = v_invite.id;
    end if;
  end if;

  return new;
end;
$$;

create trigger on_auth_user_created
  after insert on auth.users
  for each row execute function private.handle_new_auth_user();

create or replace function private.handle_auth_user_email_change()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if new.email is distinct from old.email then
    update public.users set email = coalesce(new.email, '') where id = new.id;
  end if;
  return new;
end;
$$;

create trigger on_auth_user_email_changed
  after update of email on auth.users
  for each row execute function private.handle_auth_user_email_change();

-- -----------------------------------------------------------------------------
-- messages.sender_role is derived, never client-supplied
-- -----------------------------------------------------------------------------
create or replace function private.messages_set_sender_role()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  select u.role into new.sender_role from public.users u where u.id = new.sender_id;
  if new.sender_role is null then
    raise exception 'unknown sender' using errcode = '42501';
  end if;
  return new;
end;
$$;

create trigger messages_set_sender_role
  before insert on public.messages
  for each row execute function private.messages_set_sender_role();

-- -----------------------------------------------------------------------------
-- RPC: instructor accepts the current platform terms
-- (confidentiality of client info; all payments on-platform; no solicitation)
-- -----------------------------------------------------------------------------
create or replace function public.accept_instructor_terms(p_terms_version text)
returns timestamptz
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_current text;
  v_uid uuid := (select auth.uid());
  v_at timestamptz;
begin
  if v_uid is null or private.caller_role() <> 'instructor' then
    raise exception 'only instructors can accept instructor terms' using errcode = '42501';
  end if;

  select instructor_terms_version into v_current from public.platform_settings;
  if p_terms_version is distinct from v_current then
    raise exception 'terms version % is not current (current: %)', p_terms_version, v_current
      using errcode = '22023';
  end if;

  insert into public.instructor_terms_acceptances (instructor_id, terms_version, ip_address, user_agent)
  values (
    v_uid,
    v_current,
    split_part(coalesce(private.request_header('x-forwarded-for'), ''), ',', 1),
    left(private.request_header('user-agent'), 400)
  )
  on conflict (instructor_id, terms_version) do update set accepted_at = public.instructor_terms_acceptances.accepted_at
  returning accepted_at into v_at;

  perform private.write_audit('instructor.accept_terms', 'instructor', v_uid, null,
    jsonb_build_object('terms_version', v_current));

  return v_at;
end;
$$;

-- -----------------------------------------------------------------------------
-- The ONLY way an instructor can read client-related data.
--
-- * Caller must be an active instructor who accepted the current terms.
-- * Returns only lessons assigned to the caller.
-- * Children: first name, age on the lesson date, swim level, notes.
--   Never: last name, email, phone, birth date, parent id.
-- * Address: only during the reveal window (local midnight of the lesson day
--   → lesson end + platform_settings.address_hide_after_minutes) and only for
--   live lessons. Outside the window `address` is NULL.
-- * Every row returned is written to audit_log.
-- * Range-limited (platform_settings.max_lesson_view_range_days) so the API
--   cannot be used for bulk export.
-- -----------------------------------------------------------------------------
create or replace function private.lesson_children_json(p_booking_id uuid, p_on date)
returns jsonb
language sql
stable
security definer
set search_path = ''
as $$
  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'first_name', c.first_name,
        'age', case when c.birth_date is null then null
                    else extract(year from age(p_on, c.birth_date))::int end,
        'swim_level', c.swim_level,
        'notes', c.notes
      )
      order by c.first_name
    ),
    '[]'::jsonb
  )
  from public.booking_children bc
  join public.children c on c.id = bc.child_id
  where bc.booking_id = p_booking_id
$$;

create or replace function private.lesson_address_json(p_booking_id uuid)
returns jsonb
language sql
stable
security definer
set search_path = ''
as $$
  select jsonb_build_object(
    'line1', l.address_line1,
    'line2', l.address_line2,
    'city', l.city,
    'state', l.state,
    'postal_code', l.postal_code,
    'lat', l.lat,
    'lng', l.lng,
    'access_notes', l.access_notes
  )
  from public.booking_locations l
  where l.booking_id = p_booking_id
$$;

create type public.instructor_lesson_row as (
  booking_id uuid,
  starts_at timestamptz,
  ends_at timestamptz,
  duration_minutes integer,
  status public.booking_status,
  zone_code text,
  zone_name text,
  neighborhood text,
  children jsonb,
  address jsonb,
  address_visible boolean,
  address_visible_from timestamptz,
  address_visible_until timestamptz,
  has_note boolean
);

create or replace function private.instructor_lesson_rows(p_from timestamptz, p_to timestamptz, p_booking_id uuid)
returns setof public.instructor_lesson_row
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_uid uuid := (select auth.uid());
  v_hide integer;
  r record;
  v_visible boolean;
  v_out public.instructor_lesson_row;
begin
  if not private.is_active_instructor() then
    raise exception 'not an active instructor (activation and current terms acceptance required)'
      using errcode = '42501';
  end if;

  select address_hide_after_minutes into v_hide from public.platform_settings;

  for r in
    select b.*, z.code as zone_code, z.name as zone_name
    from public.bookings b
    join public.zones z on z.id = b.zone_id
    where b.instructor_id = v_uid
      and (p_booking_id is null or b.id = p_booking_id)
      and (p_from is null or b.starts_at >= p_from)
      and (p_to is null or b.starts_at < p_to)
      and b.status in ('pending_instructor', 'confirmed', 'completed', 'no_show')
    order by b.starts_at
  loop
    v_visible := r.status = 'confirmed'
      and private.address_window_open(r.starts_at, r.ends_at, now(), v_hide);

    v_out.booking_id := r.id;
    v_out.starts_at := r.starts_at;
    v_out.ends_at := r.ends_at;
    v_out.duration_minutes := r.duration_minutes;
    v_out.status := r.status;
    v_out.zone_code := r.zone_code;
    v_out.zone_name := r.zone_name;
    v_out.neighborhood := r.neighborhood;
    v_out.children := private.lesson_children_json(r.id, private.la_date(r.starts_at));
    v_out.address := case when v_visible then private.lesson_address_json(r.id) end;
    v_out.address_visible := v_visible;
    v_out.address_visible_from := private.la_day_start(r.starts_at);
    v_out.address_visible_until := r.ends_at + make_interval(mins => v_hide);
    v_out.has_note := exists (select 1 from public.lesson_notes n where n.booking_id = r.id);

    perform private.write_audit(
      'instructor.view_lesson', 'booking', r.id, r.id,
      jsonb_build_object(
        'address_revealed', v_visible,
        'children_count', jsonb_array_length(v_out.children),
        'via', case when p_booking_id is null then 'instructor_lessons' else 'instructor_lesson' end
      )
    );

    return next v_out;
  end loop;
end;
$$;

create or replace function public.instructor_lessons(p_from date, p_to date)
returns setof public.instructor_lesson_row
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_max integer;
begin
  if p_from is null or p_to is null or p_to < p_from then
    raise exception 'invalid date range' using errcode = '22023';
  end if;
  select max_lesson_view_range_days into v_max from public.platform_settings;
  if p_to - p_from > v_max then
    raise exception 'date range too large (max % days)', v_max using errcode = '22023';
  end if;

  -- p_from / p_to are LOCAL dates; p_to is inclusive.
  return query
    select * from private.instructor_lesson_rows(
      p_from::timestamp at time zone 'America/Los_Angeles',
      (p_to + 1)::timestamp at time zone 'America/Los_Angeles',
      null
    );
end;
$$;

create or replace function public.instructor_lesson(p_booking_id uuid)
returns public.instructor_lesson_row
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_row public.instructor_lesson_row;
begin
  select * into v_row from private.instructor_lesson_rows(null, null, p_booking_id);
  if v_row.booking_id is null then
    raise exception 'lesson not found' using errcode = 'P0002';
  end if;
  return v_row;
end;
$$;

-- -----------------------------------------------------------------------------
-- Function privileges: API roles may call only these RPCs.
-- -----------------------------------------------------------------------------
revoke all on function public.accept_instructor_terms(text) from public, anon;
revoke all on function public.instructor_lessons(date, date) from public, anon;
revoke all on function public.instructor_lesson(uuid) from public, anon;
grant execute on function public.accept_instructor_terms(text) to authenticated;
grant execute on function public.instructor_lessons(date, date) to authenticated;
grant execute on function public.instructor_lesson(uuid) to authenticated;

-- private.* helpers that read sensitive tables must not be callable by API
-- roles at all (they're SECURITY DEFINER). The RLS helpers in the previous
-- migration stay executable because policies call them as the invoking role.
revoke all on function private.lesson_children_json(uuid, date) from public, anon, authenticated;
revoke all on function private.lesson_address_json(uuid) from public, anon, authenticated;
revoke all on function private.instructor_lesson_rows(timestamptz, timestamptz, uuid) from public, anon, authenticated;
revoke all on function private.write_audit(text, text, uuid, uuid, jsonb) from public, anon, authenticated;
revoke all on function private.handle_new_auth_user() from public, anon, authenticated;
revoke all on function private.handle_auth_user_email_change() from public, anon, authenticated;
revoke all on function private.messages_set_sender_role() from public, anon, authenticated;

-- ===== 20261013000500_storage.sql =====
-- =============================================================================
-- Phase 1 · Storage buckets & policies
--   instructor-photos  public read; instructor writes own folder <uid>/...
--   certifications     private; instructor writes/reads own folder; admin reads all
-- =============================================================================

insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values
  ('instructor-photos', 'instructor-photos', true, 5 * 1024 * 1024, array['image/jpeg', 'image/png', 'image/webp']),
  ('certifications', 'certifications', false, 10 * 1024 * 1024, array['image/jpeg', 'image/png', 'application/pdf'])
on conflict (id) do nothing;

create policy "instructor photos: public read"
  on storage.objects for select to anon, authenticated
  using (bucket_id = 'instructor-photos');

create policy "instructor photos: owner write"
  on storage.objects for insert to authenticated
  with check (
    bucket_id = 'instructor-photos'
    and (storage.foldername(name))[1] = (select auth.uid())::text
    and (select private.caller_role()) = 'instructor'
  );

create policy "instructor photos: owner update"
  on storage.objects for update to authenticated
  using (bucket_id = 'instructor-photos' and (storage.foldername(name))[1] = (select auth.uid())::text);

create policy "instructor photos: owner delete"
  on storage.objects for delete to authenticated
  using (bucket_id = 'instructor-photos' and (storage.foldername(name))[1] = (select auth.uid())::text);

create policy "certifications: owner or admin read"
  on storage.objects for select to authenticated
  using (
    bucket_id = 'certifications'
    and ((storage.foldername(name))[1] = (select auth.uid())::text or (select private.is_admin()))
  );

create policy "certifications: owner upload"
  on storage.objects for insert to authenticated
  with check (
    bucket_id = 'certifications'
    and (storage.foldername(name))[1] = (select auth.uid())::text
    and (select private.caller_role()) = 'instructor'
  );

-- ===== 20261014000100_county_and_instructor_profiles.sql =====
-- =============================================================================
-- Phase 2a · San Diego County only + required instructor profiles
--
-- 1. Service area is restricted to San Diego County at the database level:
--    * every ZIP on a zone, a parent's address, and a lesson address must be a
--      San Diego County ZIP (USPS prefixes 919xx, 920xx, 921xx — the whole
--      county and nothing outside it);
--    * every zone boundary vertex, and every stored home/lesson coordinate,
--      must fall inside a simplified county outline (same polygon as
--      src/lib/geo/san-diego-county.ts).
-- 2. Instructors are shown to parents by FIRST NAME only, and can't be active
--    (= visible / bookable) without a first name, a bio and a photo.
-- =============================================================================

-- -----------------------------------------------------------------------------
-- San Diego County validation helpers
-- -----------------------------------------------------------------------------
create or replace function private.is_sd_county_zip(p_zip text)
returns boolean
language sql
immutable
set search_path = ''
as $$
  select coalesce(p_zip ~ '^9(19|20|21)[0-9]{2}$', false)
$$;

create or replace function private.all_sd_county_zips(p_zips text[])
returns boolean
language sql
immutable
set search_path = ''
as $$
  select coalesce(bool_and(private.is_sd_county_zip(z)), true) from unnest(p_zips) as z
$$;

-- Bounding box of San Diego County (generous by ~1 km on land borders).
create or replace function private.within_sd_county_bbox(p_lng double precision, p_lat double precision)
returns boolean
language sql
immutable
set search_path = ''
as $$
  select p_lng between -117.62 and -116.08 and p_lat between 32.53 and 33.51
$$;

-- Simplified county outline ([lng, lat] ring). MUST match SD_COUNTY_OUTLINE in
-- src/lib/geo/san-diego-county.ts (a test asserts they are identical).
create or replace function private.sd_county_outline()
returns double precision[]
language sql
immutable
set search_path = ''
as $$
  select array[
    [-117.6, 33.386],
    [-117.51, 33.48],
    [-117.37, 33.505],
    [-117.24, 33.452],
    [-117.1, 33.432],
    [-116.95, 33.43],
    [-116.081, 33.427],
    [-116.105, 32.618],
    [-117.124, 32.534],
    [-117.15, 32.58],
    [-117.21, 32.67],
    [-117.265, 32.66],
    [-117.31, 32.78],
    [-117.33, 32.85],
    [-117.32, 32.96],
    [-117.345, 33.05],
    [-117.39, 33.15],
    [-117.46, 33.21],
    [-117.55, 33.3],
    [-117.6, 33.386]
  ]::double precision[]
$$;

-- Ray-casting point-in-polygon against the county outline.
create or replace function private.within_sd_county(p_lng double precision, p_lat double precision)
returns boolean
language plpgsql
immutable
set search_path = ''
as $$
declare
  v_ring double precision[] := private.sd_county_outline();
  v_n integer := array_length(v_ring, 1);
  v_inside boolean := false;
  v_j integer;
  xi double precision; yi double precision; xj double precision; yj double precision;
begin
  if p_lng is null or p_lat is null or not private.within_sd_county_bbox(p_lng, p_lat) then
    return false;
  end if;
  v_j := v_n;
  for i in 1..v_n loop
    xi := v_ring[i][1]; yi := v_ring[i][2];
    xj := v_ring[v_j][1]; yj := v_ring[v_j][2];
    if ((yi > p_lat) <> (yj > p_lat)) and (p_lng < (xj - xi) * (p_lat - yi) / (yj - yi) + xi) then
      v_inside := not v_inside;
    end if;
    v_j := i;
  end loop;
  return v_inside;
end;
$$;

create or replace function private.geojson_within_sd_county(p_geojson jsonb)
returns boolean
language plpgsql
immutable
set search_path = ''
as $$
declare
  v_path jsonpath;
  v_pos jsonb;
  v_count integer := 0;
begin
  if p_geojson is null then
    return true;
  end if;
  if p_geojson ->> 'type' = 'Polygon' then
    v_path := '$.coordinates[*][*]';
  elsif p_geojson ->> 'type' = 'MultiPolygon' then
    v_path := '$.coordinates[*][*][*]';
  else
    return false;
  end if;

  for v_pos in select jsonb_path_query(p_geojson, v_path) loop
    if jsonb_typeof(v_pos) <> 'array' or jsonb_array_length(v_pos) < 2
       or jsonb_typeof(v_pos -> 0) <> 'number' or jsonb_typeof(v_pos -> 1) <> 'number' then
      return false;
    end if;
    if not private.within_sd_county((v_pos ->> 0)::double precision, (v_pos ->> 1)::double precision) then
      return false;
    end if;
    v_count := v_count + 1;
  end loop;

  return v_count >= 4;  -- a closed ring needs at least 4 positions
end;
$$;

-- CHECK constraints execute these as the writing role.
grant execute on function private.is_sd_county_zip(text), private.all_sd_county_zips(text[]),
  private.within_sd_county_bbox(double precision, double precision), private.sd_county_outline(),
  private.within_sd_county(double precision, double precision), private.geojson_within_sd_county(jsonb)
  to anon, authenticated, service_role;

alter table public.zones
  add constraint zones_postal_codes_in_sd_county check (private.all_sd_county_zips(postal_codes)),
  add constraint zones_boundary_in_sd_county check (private.geojson_within_sd_county(boundary));

alter table public.parents
  add constraint parents_postal_code_in_sd_county check (postal_code is null or private.is_sd_county_zip(postal_code)),
  add constraint parents_state_ca check (state is null or state = 'CA'),
  add constraint parents_coords_in_sd_county check (lat is null or lng is null or private.within_sd_county(lng, lat));

alter table public.booking_locations
  add constraint booking_locations_postal_code_in_sd_county check (private.is_sd_county_zip(postal_code)),
  add constraint booking_locations_state_ca check (state = 'CA'),
  add constraint booking_locations_coords_in_sd_county check (lat is null or lng is null or private.within_sd_county(lng, lat));

-- -----------------------------------------------------------------------------
-- Instructor public profile: first name + bio + photo
-- -----------------------------------------------------------------------------
alter table public.instructors rename column display_name to first_name;

update public.instructors set first_name = split_part(first_name, ' ', 1);

alter table public.instructors
  -- Letters, spaces, apostrophes and hyphens only, so the one free-text field
  -- shown next to a photo can't carry a phone number, handle or email.
  add constraint instructors_first_name_format
    check (first_name ~ '^[[:alpha:]][[:alpha:] ''’-]{0,29}$'),
  add constraint instructors_bio_length
    check (bio is null or length(trim(bio)) <= 1200),
  -- Photo must be the instructor's own upload (instructor-photos/<id>/...) or a
  -- bundled image shipped with the app (/seed/...).
  add constraint instructors_photo_path_owned
    check (photo_path is null or photo_path like id::text || '/%' or photo_path like '/seed/instructors/%'),
  -- Parents only ever see active instructors, so every visible card is complete.
  add constraint instructors_profile_complete_when_active
    check (not is_active or (photo_path is not null and length(trim(coalesce(bio, ''))) >= 40));

-- Instructors may edit their own first name now that its format is constrained.
grant update (first_name) on public.instructors to authenticated;

-- Profile completeness, for onboarding checklists.
create or replace function public.instructor_profile_missing(p_instructor_id uuid default null)
returns text[]
language sql
stable
security definer
set search_path = ''
as $$
  select array_remove(array[
    case when i.photo_path is null then 'photo' end,
    case when length(trim(coalesce(i.bio, ''))) < 40 then 'bio' end,
    case when not exists (select 1 from public.instructor_zones z where z.instructor_id = i.id) then 'zones' end,
    case when not exists (select 1 from public.availability_rules r where r.instructor_id = i.id) then 'availability' end
  ], null)
  from public.instructors i
  where i.id = coalesce(p_instructor_id, (select auth.uid()))
    and (i.id = (select auth.uid()) or private.is_admin())
$$;

revoke all on function public.instructor_profile_missing(uuid) from public, anon;
grant execute on function public.instructor_profile_missing(uuid) to authenticated;

-- New-user trigger: write first_name (sanitized — user metadata is untrusted
-- and must never make signup fail on the format constraint).
create or replace function private.handle_new_auth_user()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_role public.user_role := 'parent';
  v_invite public.instructor_invites;
  v_meta jsonb := coalesce(new.raw_user_meta_data, '{}'::jsonb);
  v_full_name text := nullif(trim(coalesce(v_meta ->> 'full_name', v_meta ->> 'name', '')), '');
  v_first text := nullif(trim(coalesce(v_meta ->> 'first_name', v_meta ->> 'given_name', '')), '');
  v_last text := nullif(trim(coalesce(v_meta ->> 'last_name', v_meta ->> 'family_name', '')), '');
  v_public_first text;
  v_default_rate integer;
begin
  select * into v_invite
  from public.instructor_invites i
  where lower(i.email) = lower(new.email)
    and i.accepted_at is null
    and i.expires_at > now()
  order by i.created_at desc
  limit 1;

  if found then
    v_role := 'instructor';
  elsif (new.raw_app_meta_data ->> 'role') in ('instructor', 'admin') then
    v_role := (new.raw_app_meta_data ->> 'role')::public.user_role;
  end if;

  if v_first is null and v_full_name is not null then
    v_first := split_part(v_full_name, ' ', 1);
    v_last := coalesce(v_last, nullif(trim(substr(v_full_name, length(v_first) + 1)), ''));
  end if;

  insert into public.users (id, role, email, first_name, last_name)
  values (new.id, v_role, coalesce(new.email, ''), v_first, v_last)
  on conflict (id) do nothing;

  if v_role = 'parent' then
    insert into public.parents (id) values (new.id) on conflict (id) do nothing;
  elsif v_role = 'instructor' then
    select default_instructor_pay_cents_per_hour into v_default_rate from public.platform_settings;

    v_public_first := left(trim(regexp_replace(coalesce(v_first, ''), '[^[:alpha:] ''’-]', '', 'g')), 30);
    if v_public_first !~ '^[[:alpha:]]' then
      v_public_first := 'Instructor';
    end if;

    insert into public.instructors (id, first_name, is_active)
    values (new.id, v_public_first, false)
    on conflict (id) do nothing;

    insert into public.instructor_private (instructor_id, pay_rate_cents_per_hour)
    values (new.id, coalesce(v_invite.pay_rate_cents_per_hour, v_default_rate, 4000))
    on conflict (instructor_id) do nothing;

    if v_invite.id is not null then
      update public.instructor_invites
      set accepted_at = now(), accepted_user_id = new.id
      where id = v_invite.id;
    end if;
  end if;

  return new;
end;
$$;

revoke all on function private.handle_new_auth_user() from public, anon, authenticated;

-- ===== 20261014000200_scheduling.sql =====
-- =============================================================================
-- Phase 2b · Scheduling: settings, travel-buffer enforcement, booking offers
-- =============================================================================

alter table public.platform_settings
  add column slot_step_minutes integer not null default 30 check (slot_step_minutes in (15, 30, 60)),
  add column min_booking_notice_hours integer not null default 24 check (min_booking_notice_hours >= 0),
  add column max_booking_horizon_days integer not null default 60 check (max_booking_horizon_days between 1 and 365),
  add column offer_min_lead_minutes integer not null default 120 check (offer_min_lead_minutes >= 0);

alter table public.bookings
  -- Admin-only escape hatch for manual bookings that knowingly skip the buffer.
  add column buffer_override boolean not null default false,
  -- Set when no instructor accepted / no match left; surfaced on the admin dashboard.
  add column needs_attention boolean not null default false,
  add column attention_reason text;

create index bookings_needs_attention_idx on public.bookings (needs_attention) where needs_attention;

-- -----------------------------------------------------------------------------
-- Travel buffer between two zones (minutes), falling back to the default.
-- -----------------------------------------------------------------------------
create or replace function private.travel_buffer_minutes(p_from_zone uuid, p_to_zone uuid)
returns integer
language sql
stable
security definer
set search_path = ''
as $$
  select coalesce(
    (select b.buffer_minutes from public.zone_travel_buffers b
      where b.from_zone_id = p_from_zone and b.to_zone_id = p_to_zone),
    (select s.default_travel_buffer_minutes from public.platform_settings s),
    30
  )
$$;

-- -----------------------------------------------------------------------------
-- DB-level guarantee: an instructor always has the travel buffer between two
-- live lessons. The exclusion constraint already blocks overlaps; this trigger
-- extends it with the zone-pair buffer. A per-instructor advisory lock
-- serializes concurrent bookings so two checkouts can't both squeeze in.
-- -----------------------------------------------------------------------------
create or replace function private.bookings_enforce_travel_buffer()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_conflict uuid;
  v_live public.booking_status[] := array['pending_payment', 'pending_instructor', 'confirmed', 'completed']::public.booking_status[];
begin
  if new.instructor_id is null or not (new.status = any (v_live)) or new.buffer_override then
    return new;
  end if;

  if tg_op = 'UPDATE'
     and new.instructor_id is not distinct from old.instructor_id
     and new.starts_at = old.starts_at and new.ends_at = old.ends_at
     and new.zone_id = old.zone_id
     and old.status = any (v_live) then
    return new;  -- nothing schedule-relevant changed
  end if;

  perform pg_advisory_xact_lock(hashtextextended('instructor-schedule:' || new.instructor_id::text, 0));

  select b.id into v_conflict
  from public.bookings b
  where b.instructor_id = new.instructor_id
    and b.id <> new.id
    and b.status = any (v_live)
    and b.starts_at < new.ends_at + make_interval(mins => private.travel_buffer_minutes(new.zone_id, b.zone_id))
    and new.starts_at < b.ends_at + make_interval(mins => private.travel_buffer_minutes(b.zone_id, new.zone_id))
  limit 1;

  if v_conflict is not null then
    raise exception 'travel buffer conflict with booking %', v_conflict
      using errcode = 'SB001', hint = 'Choose another time or instructor.';
  end if;

  return new;
end;
$$;

create trigger bookings_enforce_travel_buffer
  before insert or update of instructor_id, starts_at, ends_at, zone_id, status, buffer_override on public.bookings
  for each row execute function private.bookings_enforce_travel_buffer();

-- -----------------------------------------------------------------------------
-- RPC: instructor accepts or declines a booking request.
-- Accept → booking confirmed. Decline / expired → booking released
-- (instructor_id = null); the app then auto-offers the next ranked match
-- (src/lib/scheduling/offers.ts).
-- -----------------------------------------------------------------------------
create or replace function public.respond_to_booking_offer(p_offer_id uuid, p_accept boolean, p_reason text default null)
returns public.offer_status
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_uid uuid := (select auth.uid());
  v_offer public.booking_offers;
begin
  if not private.is_active_instructor() then
    raise exception 'not an active instructor' using errcode = '42501';
  end if;

  select * into v_offer from public.booking_offers o
  where o.id = p_offer_id and o.instructor_id = v_uid
  for update;
  if not found then
    raise exception 'offer not found' using errcode = 'P0002';
  end if;
  if v_offer.status <> 'pending' then
    raise exception 'offer is no longer pending (%)', v_offer.status using errcode = 'SB002';
  end if;

  if v_offer.expires_at <= now() then
    update public.booking_offers set status = 'expired', responded_at = now() where id = v_offer.id;
    update public.bookings set instructor_id = null
      where id = v_offer.booking_id and instructor_id = v_uid and status = 'pending_instructor';
    return 'expired';
  end if;

  if p_accept then
    update public.bookings
      set status = 'confirmed', confirmed_at = now(), needs_attention = false, attention_reason = null
      where id = v_offer.booking_id and instructor_id = v_uid and status = 'pending_instructor';
    if not found then
      raise exception 'booking is no longer awaiting this instructor' using errcode = 'SB002';
    end if;
    update public.booking_offers set status = 'accepted', responded_at = now() where id = v_offer.id;
    perform private.write_audit('instructor.accept_offer', 'booking', v_offer.booking_id, v_offer.booking_id, '{}'::jsonb);
    return 'accepted';
  end if;

  update public.booking_offers
    set status = 'declined', responded_at = now(), decline_reason = left(p_reason, 500)
    where id = v_offer.id;
  update public.bookings set instructor_id = null
    where id = v_offer.booking_id and instructor_id = v_uid and status = 'pending_instructor';
  perform private.write_audit('instructor.decline_offer', 'booking', v_offer.booking_id, v_offer.booking_id,
    jsonb_build_object('reason', left(p_reason, 500)));
  return 'declined';
end;
$$;

revoke all on function public.respond_to_booking_offer(uuid, boolean, text) from public, anon;
grant execute on function public.respond_to_booking_offer(uuid, boolean, text) to authenticated;

-- -----------------------------------------------------------------------------
-- Scheduling snapshot for the engine (service role only).
-- One round-trip with everything findSlots() needs for a date range. Contains
-- no parent/child PII — just instructor capabilities, availability and
-- occupied (instructor, zone, time) blocks.
-- -----------------------------------------------------------------------------
create or replace function public.scheduling_snapshot(p_from date, p_to date)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_from_ts timestamptz;
  v_to_ts timestamptz;
begin
  if p_from is null or p_to is null or p_to < p_from or p_to - p_from > 92 then
    raise exception 'invalid range (max 92 days)' using errcode = '22023';
  end if;
  v_from_ts := (p_from - 1)::timestamp at time zone 'America/Los_Angeles';
  v_to_ts := (p_to + 2)::timestamp at time zone 'America/Los_Angeles';

  return jsonb_build_object(
    'settings', (
      select jsonb_build_object(
        'slotStepMinutes', s.slot_step_minutes,
        'minNoticeHours', s.min_booking_notice_hours,
        'maxHorizonDays', s.max_booking_horizon_days,
        'defaultBufferMinutes', s.default_travel_buffer_minutes,
        'bookingRequestWindowHours', s.booking_request_window_hours,
        'offerMinLeadMinutes', s.offer_min_lead_minutes,
        'paymentHoldMinutes', s.payment_hold_minutes,
        'maxChildrenPerLesson', s.max_children_per_lesson,
        'minLessonMinutes', coalesce((select min(lp.duration_minutes) from public.lesson_prices lp where lp.is_active), 30)
      ) from public.platform_settings s
    ),
    'pricing', (
      select jsonb_build_object('neighborhoodWindowMinutes', p.neighborhood_window_minutes)
      from public.pricing_config p
    ),
    'zones', (
      select coalesce(jsonb_agg(jsonb_build_object(
        'id', z.id, 'code', z.code, 'name', z.name,
        'minBookingMinutes', z.min_booking_minutes, 'isBookable', z.is_bookable
      ) order by z.sort_order), '[]'::jsonb)
      from public.zones z
    ),
    'buffers', (
      select coalesce(jsonb_agg(jsonb_build_object('from', b.from_zone_id, 'to', b.to_zone_id, 'minutes', b.buffer_minutes)), '[]'::jsonb)
      from public.zone_travel_buffers b
    ),
    'instructors', (
      select coalesce(jsonb_agg(jsonb_build_object(
        'id', i.id,
        'firstName', i.first_name,
        'photoPath', i.photo_path,
        'specialties', to_jsonb(i.specialties),
        'levelsTaught', to_jsonb(i.levels_taught),
        'minChildAgeMonths', i.min_child_age_months,
        'maxChildrenPerLesson', i.max_children_per_lesson,
        'isAcceptingNewClients', i.is_accepting_new_clients,
        'sortOrder', i.sort_order,
        'zoneIds', (select coalesce(jsonb_agg(iz.zone_id), '[]'::jsonb) from public.instructor_zones iz where iz.instructor_id = i.id)
      ) order by i.sort_order, i.id), '[]'::jsonb)
      from public.instructors i
      where i.is_active and private.has_accepted_current_terms(i.id)
    ),
    'rules', (
      select coalesce(jsonb_agg(jsonb_build_object(
        'instructorId', r.instructor_id, 'weekday', r.weekday,
        'startTime', to_char(r.start_time, 'HH24:MI'), 'endTime', to_char(r.end_time, 'HH24:MI'),
        'effectiveFrom', r.effective_from, 'effectiveUntil', r.effective_until
      )), '[]'::jsonb)
      from public.availability_rules r
      where r.effective_from <= p_to and (r.effective_until is null or r.effective_until >= p_from)
    ),
    'overrides', (
      select coalesce(jsonb_agg(jsonb_build_object(
        'instructorId', o.instructor_id, 'date', o.date, 'kind', o.kind,
        'startTime', to_char(o.start_time, 'HH24:MI'), 'endTime', to_char(o.end_time, 'HH24:MI')
      )), '[]'::jsonb)
      from public.availability_overrides o
      where o.date between p_from and p_to
    ),
    'bookings', (
      select coalesce(jsonb_agg(jsonb_build_object(
        'id', b.id, 'instructorId', b.instructor_id, 'zoneId', b.zone_id,
        'start', b.starts_at, 'end', b.ends_at
      )), '[]'::jsonb)
      from public.bookings b
      where b.instructor_id is not null
        and b.status in ('pending_payment', 'pending_instructor', 'confirmed', 'completed')
        and b.starts_at < v_to_ts and b.ends_at > v_from_ts
    )
  );
end;
$$;

revoke all on function public.scheduling_snapshot(date, date) from public, anon, authenticated;
grant execute on function public.scheduling_snapshot(date, date) to service_role;

revoke all on function private.bookings_enforce_travel_buffer() from public, anon, authenticated;

-- ===== 20261014000300_offer_automation.sql =====
-- =============================================================================
-- Phase 2c · Booking request automation (service role only)
--
-- The app's offer loop (src/lib/scheduling/offers.ts) ranks instructors with
-- the scheduling engine, then calls assign_booking_offer() for the best one.
-- Assignment + offer creation is atomic, and the travel-buffer trigger and
-- exclusion constraint still guard the assignment, so a race simply raises
-- and the loop moves on to the next candidate.
-- =============================================================================

create or replace function public.assign_booking_offer(
  p_booking_id uuid,
  p_instructor_id uuid,
  p_expires_at timestamptz,
  p_lesson_summary jsonb
)
returns uuid
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_rank integer;
  v_offer_id uuid;
begin
  update public.bookings
    set instructor_id = p_instructor_id
    where id = p_booking_id and status = 'pending_instructor' and instructor_id is null;
  if not found then
    raise exception 'booking % is not awaiting an instructor', p_booking_id using errcode = 'SB002';
  end if;

  if exists (select 1 from public.booking_offers o where o.booking_id = p_booking_id and o.instructor_id = p_instructor_id) then
    raise exception 'instructor was already offered this booking' using errcode = 'SB003';
  end if;

  select coalesce(max(o.rank), 0) + 1 into v_rank from public.booking_offers o where o.booking_id = p_booking_id;

  insert into public.booking_offers (booking_id, instructor_id, rank, status, lesson_summary, expires_at)
  values (p_booking_id, p_instructor_id, v_rank, 'pending', coalesce(p_lesson_summary, '{}'::jsonb), p_expires_at)
  returning id into v_offer_id;

  return v_offer_id;
end;
$$;

-- Pending offers past their deadline → expired; their bookings are released.
-- Returns the released booking ids so the app can offer them onward.
create or replace function public.expire_stale_offers()
returns setof uuid
language sql
security definer
set search_path = ''
as $$
  with expired as (
    update public.booking_offers
      set status = 'expired', responded_at = now()
      where status = 'pending' and expires_at <= now()
      returning booking_id, instructor_id
  ), released as (
    update public.bookings b
      set instructor_id = null
      from expired e
      where b.id = e.booking_id and b.instructor_id = e.instructor_id and b.status = 'pending_instructor'
      returning b.id
  )
  select id from released
$$;

-- Bookings whose Stripe Checkout hold lapsed free their slot.
create or replace function public.expire_payment_holds()
returns setof uuid
language sql
security definer
set search_path = ''
as $$
  update public.bookings
    set status = 'expired'
    where status = 'pending_payment' and hold_expires_at is not null and hold_expires_at <= now()
    returning id
$$;

-- Bookings stuck awaiting an instructor with nobody currently offered
-- (e.g. a crash between decline and re-offer). The cron re-runs these.
create or replace function public.bookings_awaiting_offer()
returns setof uuid
language sql
stable
security definer
set search_path = ''
as $$
  select b.id from public.bookings b
  where b.status = 'pending_instructor' and b.instructor_id is null and not b.needs_attention
$$;

revoke all on function public.assign_booking_offer(uuid, uuid, timestamptz, jsonb) from public, anon, authenticated;
revoke all on function public.expire_stale_offers() from public, anon, authenticated;
revoke all on function public.expire_payment_holds() from public, anon, authenticated;
revoke all on function public.bookings_awaiting_offer() from public, anon, authenticated;
grant execute on function public.assign_booking_offer(uuid, uuid, timestamptz, jsonb) to service_role;
grant execute on function public.expire_stale_offers() to service_role;
grant execute on function public.expire_payment_holds() to service_role;
grant execute on function public.bookings_awaiting_offer() to service_role;

-- ===== 20261015000100_booking_payments.sql =====
-- =============================================================================
-- Phase 3 · Booking + payments
--
-- Payment flow: the server creates bookings in `pending_payment` (instructor
-- assigned, slot held until hold_expires_at) plus a pending `payments` row,
-- then sends the parent to Stripe Checkout. The Stripe webhook calls
-- fulfillment, which flips bookings to `pending_instructor` and opens the
-- instructor's accept/decline request via start_booking_request().
-- =============================================================================

-- Stripe Checkout sessions last at least 30 minutes; the hold must outlive them.
alter table public.platform_settings alter column payment_hold_minutes set default 35;
update public.platform_settings set payment_hold_minutes = 35 where payment_hold_minutes < 35;
alter table public.platform_settings
  add constraint platform_settings_hold_covers_checkout check (payment_hold_minutes >= 31),
  add column recurring_term_weeks integer[] not null default '{4,8}'
    check (array_length(recurring_term_weeks, 1) >= 1 and 1 < all (recurring_term_weeks) and 27 > all (recurring_term_weeks));

alter table public.payments
  add column kind text not null default 'booking' check (kind in ('booking', 'package', 'series', 'day_pass')),
  add column stripe_refund_ids text[] not null default '{}';

alter table public.bookings
  -- The payment that paid for this lesson (single or series). Package lessons
  -- have package_id instead.
  add column payment_id uuid references public.payments (id) on delete set null;

create index bookings_payment_idx on public.bookings (payment_id);

-- Idempotency for Stripe webhooks (Stripe retries and may deliver twice).
create table public.stripe_events (
  id text primary key,
  type text not null,
  received_at timestamptz not null default now(),
  processed_at timestamptz
);
alter table public.stripe_events enable row level security;
grant select on public.stripe_events to authenticated;
create policy stripe_events_admin_select on public.stripe_events for select to authenticated
  using ((select private.is_admin()));

-- Parents read their packages/series to show credits and terms (policies exist).
-- Parents may read receipts for their own payments (policy exists).

-- -----------------------------------------------------------------------------
-- Paid → open the instructor request (atomic).
-- -----------------------------------------------------------------------------
create or replace function public.start_booking_request(p_booking_id uuid, p_expires_at timestamptz, p_lesson_summary jsonb)
returns uuid
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_booking public.bookings;
  v_offer_id uuid;
begin
  select * into v_booking from public.bookings where id = p_booking_id for update;
  if not found then
    raise exception 'booking not found' using errcode = 'P0002';
  end if;
  if v_booking.status <> 'pending_payment' then
    raise exception 'booking % is %, not pending_payment', p_booking_id, v_booking.status using errcode = 'SB002';
  end if;

  update public.bookings
    set status = 'pending_instructor', hold_expires_at = null
    where id = p_booking_id;

  if v_booking.instructor_id is null then
    return null;  -- the offer loop will assign someone
  end if;

  insert into public.booking_offers (booking_id, instructor_id, rank, status, lesson_summary, expires_at)
  values (p_booking_id, v_booking.instructor_id, 1, 'pending', coalesce(p_lesson_summary, '{}'::jsonb), p_expires_at)
  on conflict (booking_id, instructor_id) do nothing
  returning id into v_offer_id;
  return v_offer_id;
end;
$$;

-- -----------------------------------------------------------------------------
-- Package credits (atomic; never below zero; respects expiry).
-- -----------------------------------------------------------------------------
create or replace function public.consume_package_credit(p_package_id uuid, p_parent_id uuid)
returns integer
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_remaining integer;
begin
  update public.packages
    set lessons_remaining = lessons_remaining - 1,
        status = case when lessons_remaining - 1 = 0 then 'exhausted'::public.package_status else status end
    where id = p_package_id and parent_id = p_parent_id and status = 'active'
      and lessons_remaining > 0 and (expires_at is null or expires_at > now())
    returning lessons_remaining into v_remaining;
  if not found then
    raise exception 'no usable credit on package %', p_package_id using errcode = 'SB004';
  end if;
  return v_remaining;
end;
$$;

create or replace function public.restore_package_credit(p_package_id uuid)
returns integer
language sql
security definer
set search_path = ''
as $$
  update public.packages
    set lessons_remaining = least(lesson_count, lessons_remaining + 1),
        status = case when status = 'exhausted' then 'active'::public.package_status else status end
    where id = p_package_id and status in ('active', 'exhausted')
    returning lessons_remaining
$$;

-- -----------------------------------------------------------------------------
-- Promo codes: atomic redemption that honors max_redemptions.
-- -----------------------------------------------------------------------------
create or replace function public.redeem_discount_code(p_code_id uuid)
returns boolean
language sql
security definer
set search_path = ''
as $$
  with r as (
    update public.discount_codes
      set redemptions = redemptions + 1
      where id = p_code_id and is_active
        and (max_redemptions is null or redemptions < max_redemptions)
      returning 1
  )
  select exists (select 1 from r)
$$;

revoke all on function public.start_booking_request(uuid, timestamptz, jsonb) from public, anon, authenticated;
revoke all on function public.consume_package_credit(uuid, uuid) from public, anon, authenticated;
revoke all on function public.restore_package_credit(uuid) from public, anon, authenticated;
revoke all on function public.redeem_discount_code(uuid) from public, anon, authenticated;
grant execute on function public.start_booking_request(uuid, timestamptz, jsonb) to service_role;
grant execute on function public.consume_package_credit(uuid, uuid) to service_role;
grant execute on function public.restore_package_credit(uuid) to service_role;
grant execute on function public.redeem_discount_code(uuid) to service_role;

-- -----------------------------------------------------------------------------
-- One transaction for an entire checkout: package/series row, payment row,
-- every lesson (+ swimmers, address, per-lesson pricing). The exclusion
-- constraint and travel-buffer trigger guard each lesson, so if any slot was
-- taken in the meantime nothing is written at all.
--
-- p = {
--   parent_id, kind: single|package|recurring|package_credit,
--   instructor_id, requested_instructor_id, zone_id, neighborhood,
--   child_ids: [uuid], location: {address_line1, address_line2, city, postal_code, lat, lng, google_place_id, access_notes},
--   occurrences: [{starts_at, ends_at, is_neighborhood_slot, pricing: {base_cents, ...booking_pricing columns, total_cents}}],
--   amount_cents, currency, description, discount_code_id, pricing_snapshot,
--   package: {offering_id, lesson_count, duration_minutes, unit_price_cents, discount_pct, total_cents},   (kind=package)
--   series: {weekday, start_time, duration_minutes, starts_on, ends_on, discount_pct},                    (kind=recurring)
--   package_id                                                                                             (kind=package_credit)
-- }
-- -----------------------------------------------------------------------------
create or replace function public.create_booking_hold(p jsonb)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_parent uuid := (p ->> 'parent_id')::uuid;
  v_kind text := p ->> 'kind';
  v_amount integer := coalesce((p ->> 'amount_cents')::integer, 0);
  v_children integer := jsonb_array_length(p -> 'child_ids');
  v_hold timestamptz;
  v_payment_id uuid;
  v_package_id uuid;
  v_series_id uuid;
  v_booking_id uuid;
  v_ids uuid[] := '{}';
  v_occ jsonb;
  v_loc jsonb := p -> 'location';
begin
  if v_kind not in ('single', 'package', 'recurring', 'package_credit') then
    raise exception 'invalid kind %', v_kind using errcode = '22023';
  end if;
  if v_children < 1 or exists (
    select 1 from jsonb_array_elements_text(p -> 'child_ids') c
    where not exists (select 1 from public.children ch where ch.id = c::uuid and ch.parent_id = v_parent and ch.is_active)
  ) then
    raise exception 'swimmers must belong to this family' using errcode = '22023';
  end if;

  select now() + make_interval(mins => s.payment_hold_minutes) into v_hold from public.platform_settings s;

  if v_kind = 'package' then
    insert into public.packages (parent_id, offering_id, lesson_count, lessons_remaining, duration_minutes, children_count, zone_id,
                                 unit_price_cents, discount_pct, total_cents, status)
    values (v_parent, (p #>> '{package,offering_id}')::uuid, (p #>> '{package,lesson_count}')::integer,
            (p #>> '{package,lesson_count}')::integer - 1,  -- the first lesson is booked now
            (p #>> '{package,duration_minutes}')::integer, v_children, (p ->> 'zone_id')::uuid,
            (p #>> '{package,unit_price_cents}')::integer, (p #>> '{package,discount_pct}')::numeric,
            (p #>> '{package,total_cents}')::integer, 'pending_payment')
    returning id into v_package_id;
  elsif v_kind = 'recurring' then
    insert into public.booking_series (parent_id, instructor_id, zone_id, weekday, start_time, duration_minutes, children_count,
                                       starts_on, ends_on, discount_pct, status)
    values (v_parent, (p ->> 'instructor_id')::uuid, (p ->> 'zone_id')::uuid, (p #>> '{series,weekday}')::smallint,
            (p #>> '{series,start_time}')::time, (p #>> '{series,duration_minutes}')::integer, v_children,
            (p #>> '{series,starts_on}')::date, (p #>> '{series,ends_on}')::date, (p #>> '{series,discount_pct}')::numeric,
            case when v_amount > 0 then 'pending_payment'::public.series_status else 'active'::public.series_status end)
    returning id into v_series_id;
  elsif v_kind = 'package_credit' then
    v_package_id := (p ->> 'package_id')::uuid;
    perform public.consume_package_credit(v_package_id, v_parent);
  end if;

  if v_amount > 0 then
    insert into public.payments (parent_id, package_id, series_id, amount_cents, currency, kind, description, status)
    values (v_parent, v_package_id, v_series_id, v_amount, coalesce(p ->> 'currency', 'usd'),
            case v_kind when 'package' then 'package' when 'recurring' then 'series' else 'booking' end,
            left(p ->> 'description', 500), 'pending')
    returning id into v_payment_id;
  end if;

  for v_occ in select value from jsonb_array_elements(p -> 'occurrences') loop
    insert into public.bookings (parent_id, instructor_id, requested_instructor_id, zone_id, neighborhood, starts_at, ends_at,
                                 status, kind, series_id, package_id, children_count, is_neighborhood_slot, hold_expires_at,
                                 source, created_by, payment_id)
    values (v_parent, (p ->> 'instructor_id')::uuid, (p ->> 'requested_instructor_id')::uuid, (p ->> 'zone_id')::uuid,
            p ->> 'neighborhood', (v_occ ->> 'starts_at')::timestamptz, (v_occ ->> 'ends_at')::timestamptz,
            'pending_payment',
            case v_kind when 'recurring' then 'recurring'::public.booking_kind
                        when 'single' then 'single'::public.booking_kind
                        else 'package'::public.booking_kind end,
            v_series_id, v_package_id, v_children, coalesce((v_occ ->> 'is_neighborhood_slot')::boolean, false),
            case when v_amount > 0 then v_hold end, 'web', v_parent,
            case when v_kind in ('single', 'recurring') then v_payment_id end)
    returning id into v_booking_id;

    insert into public.booking_children (booking_id, child_id)
    select v_booking_id, c::uuid from jsonb_array_elements_text(p -> 'child_ids') c;

    insert into public.booking_locations (booking_id, address_line1, address_line2, city, postal_code, lat, lng, google_place_id, access_notes)
    values (v_booking_id, v_loc ->> 'address_line1', nullif(v_loc ->> 'address_line2', ''), v_loc ->> 'city', v_loc ->> 'postal_code',
            (v_loc ->> 'lat')::double precision, (v_loc ->> 'lng')::double precision, v_loc ->> 'google_place_id',
            nullif(v_loc ->> 'access_notes', ''));

    insert into public.booking_pricing (booking_id, currency, base_cents, extra_children_cents, travel_fee_cents,
                                        neighborhood_discount_cents, package_discount_cents, series_discount_cents,
                                        promo_discount_cents, discount_code_id, total_cents, snapshot)
    values (v_booking_id, coalesce(p ->> 'currency', 'usd'),
            coalesce((v_occ #>> '{pricing,base_cents}')::integer, 0),
            coalesce((v_occ #>> '{pricing,extra_children_cents}')::integer, 0),
            coalesce((v_occ #>> '{pricing,travel_fee_cents}')::integer, 0),
            coalesce((v_occ #>> '{pricing,neighborhood_discount_cents}')::integer, 0),
            coalesce((v_occ #>> '{pricing,package_discount_cents}')::integer, 0),
            coalesce((v_occ #>> '{pricing,series_discount_cents}')::integer, 0),
            coalesce((v_occ #>> '{pricing,promo_discount_cents}')::integer, 0),
            (p ->> 'discount_code_id')::uuid,
            (v_occ #>> '{pricing,total_cents}')::integer,
            coalesce(p -> 'pricing_snapshot', '{}'::jsonb));

    v_ids := v_ids || v_booking_id;
  end loop;

  if v_payment_id is not null and v_kind = 'single' then
    update public.payments set booking_id = v_ids[1] where id = v_payment_id;
  end if;

  return jsonb_build_object('payment_id', v_payment_id, 'booking_ids', to_jsonb(v_ids), 'package_id', v_package_id, 'series_id', v_series_id);
end;
$$;

-- Abandoned / expired checkout: free the slots and void the pending rows.
create or replace function public.release_booking_hold(p_payment_id uuid)
returns integer
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_payment public.payments;
  v_count integer;
begin
  update public.payments set status = 'cancelled'
    where id = p_payment_id and status = 'pending'
    returning * into v_payment;
  if not found then
    return 0;
  end if;

  update public.bookings set status = 'expired', hold_expires_at = null
    where status = 'pending_payment'
      and (payment_id = p_payment_id or (v_payment.package_id is not null and package_id = v_payment.package_id));
  get diagnostics v_count = row_count;

  update public.packages set status = 'expired' where id = v_payment.package_id and status = 'pending_payment';
  update public.booking_series set status = 'cancelled' where id = v_payment.series_id and status = 'pending_payment';
  return v_count;
end;
$$;

revoke all on function public.create_booking_hold(jsonb) from public, anon, authenticated;
revoke all on function public.release_booking_hold(uuid) from public, anon, authenticated;
grant execute on function public.create_booking_hold(jsonb) to service_role;
grant execute on function public.release_booking_hold(uuid) to service_role;

-- Holds whose payment lapsed (cron) — also void their payment rows.
create or replace function public.expire_payment_holds()
returns setof uuid
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_payment uuid;
begin
  for v_payment in
    select distinct b.payment_id from public.bookings b
    where b.status = 'pending_payment' and b.hold_expires_at is not null and b.hold_expires_at <= now() and b.payment_id is not null
    union
    select distinct p.id from public.payments p
    join public.bookings b on b.package_id = p.package_id
    where p.status = 'pending' and b.status = 'pending_payment' and b.hold_expires_at is not null and b.hold_expires_at <= now()
  loop
    perform public.release_booking_hold(v_payment);
  end loop;

  return query
    update public.bookings set status = 'expired'
    where status = 'pending_payment' and hold_expires_at is not null and hold_expires_at <= now()
    returning id;
end;
$$;
revoke all on function public.expire_payment_holds() from public, anon, authenticated;
grant execute on function public.expire_payment_holds() to service_role;

-- ===== 20261016000100_packages_and_contact_sharing.sql =====
-- =============================================================================
-- Packages (6 / 8 / 14 lessons) + contact sharing for package families
--
-- Contact rule (owner decision): once a family has PAID for a package and an
-- instructor has ACCEPTED a lesson from it, that family and that instructor
-- may see each other's name, phone and email. Single lessons and weekly
-- series stay masked. Other instructors never see anything. Every contact
-- view is audited. platform_settings.contact_sharing = 'never' turns it off.
-- =============================================================================

-- -----------------------------------------------------------------------------
-- Default catalog (also needed in production, where seed.sql never runs).
-- Never overwrites values an admin has changed.
-- -----------------------------------------------------------------------------
insert into public.lesson_prices (duration_minutes, price_cents, label, sort_order) values
  (30, 6500, '30 minutes', 1),
  (60, 9000, '60 minutes', 2),
  (90, 13000, '90 minutes', 3)
on conflict (duration_minutes) do nothing;

update public.package_offerings set is_active = false where lesson_count = 4;

insert into public.package_offerings (name, lesson_count, discount_pct, validity_days, sort_order) values
  ('6-Lesson Package', 6, 5, 150, 1),
  ('8-Lesson Package', 8, 10, 180, 2),
  ('14-Lesson Package', 14, 15, 270, 3)
on conflict (lesson_count) do nothing;

-- -----------------------------------------------------------------------------
-- Contact sharing
-- -----------------------------------------------------------------------------
alter table public.platform_settings
  add column contact_sharing text not null default 'package_instructor'
    check (contact_sharing in ('never', 'package_instructor'));

create or replace function private.contact_shared(p_parent_id uuid, p_instructor_id uuid)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select (select s.contact_sharing from public.platform_settings s) = 'package_instructor'
    and exists (
      select 1
      from public.bookings b
      join public.packages p on p.id = b.package_id
      where b.parent_id = p_parent_id
        and b.instructor_id = p_instructor_id
        and b.status in ('confirmed', 'completed')
        and p.status in ('active', 'exhausted')   -- paid; not refunded/expired-unpaid
    )
$$;

-- Parent → contact details of their package instructors.
create or replace function public.my_instructor_contacts()
returns table (instructor_id uuid, first_name text, last_name text, email text, phone text)
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_uid uuid := (select auth.uid());
  r record;
begin
  if private.caller_role() is distinct from 'parent' then
    raise exception 'parents only' using errcode = '42501';
  end if;

  for r in
    select i.id, i.first_name, u.last_name, u.email, u.phone
    from public.instructors i
    join public.users u on u.id = i.id
    where private.contact_shared(v_uid, i.id)
    order by i.first_name
  loop
    perform private.write_audit('parent.view_instructor_contact', 'instructor', r.id, null, '{}'::jsonb);
    instructor_id := r.id; first_name := r.first_name; last_name := r.last_name; email := r.email; phone := r.phone;
    return next;
  end loop;
end;
$$;

-- Instructor → contact details of their package families.
create or replace function public.my_family_contacts()
returns table (parent_id uuid, first_name text, last_name text, email text, phone text, children text[])
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_uid uuid := (select auth.uid());
  r record;
begin
  if not private.is_active_instructor() then
    raise exception 'not an active instructor' using errcode = '42501';
  end if;

  for r in
    select p.id, u.first_name, u.last_name, u.email, u.phone,
           coalesce((select array_agg(c.first_name order by c.first_name) from public.children c where c.parent_id = p.id and c.is_active), '{}') as kids
    from public.parents p
    join public.users u on u.id = p.id
    where private.contact_shared(p.id, v_uid)
    order by u.last_name, u.first_name
  loop
    perform private.write_audit('instructor.view_family_contact', 'parent', r.id, null, '{}'::jsonb);
    parent_id := r.id; first_name := r.first_name; last_name := r.last_name; email := r.email; phone := r.phone; children := r.kids;
    return next;
  end loop;
end;
$$;

revoke all on function private.contact_shared(uuid, uuid) from public, anon, authenticated;
revoke all on function public.my_instructor_contacts() from public, anon;
revoke all on function public.my_family_contacts() from public, anon;
grant execute on function public.my_instructor_contacts() to authenticated;
grant execute on function public.my_family_contacts() to authenticated;

