-- ===== 20261016000200_notifications_and_notes.sql =====
-- =============================================================================
-- Phase 4 · Notifications outbox + instructor progress notes
-- =============================================================================

-- -----------------------------------------------------------------------------
-- Notification outbox. Every email/SMS is rendered and stored here first, then
-- delivered (immediately, and retried by the cron). dedupe_key makes each
-- notification idempotent: the same event can fire twice and send once.
-- -----------------------------------------------------------------------------
create type public.notification_channel as enum ('email', 'sms');
create type public.notification_status as enum ('pending', 'sent', 'failed', 'skipped');

create table public.notifications (
  id uuid primary key default gen_random_uuid(),
  user_id uuid references public.users (id) on delete cascade,   -- null for admin alerts
  to_address text not null,                                      -- email or E.164 phone
  channel public.notification_channel not null,
  template text not null,
  booking_id uuid references public.bookings (id) on delete set null,
  subject text,
  body_text text not null,
  body_html text,
  dedupe_key text not null unique,
  status public.notification_status not null default 'pending',
  attempts integer not null default 0,
  last_error text,
  provider text,                                                 -- resend | twilio | log
  provider_message_id text,
  next_attempt_at timestamptz not null default now(),
  sent_at timestamptz,
  created_at timestamptz not null default now()
);

create index notifications_due_idx on public.notifications (next_attempt_at) where status in ('pending', 'failed');
create index notifications_user_idx on public.notifications (user_id, created_at desc);
create index notifications_booking_idx on public.notifications (booking_id);

alter table public.notifications enable row level security;
grant select on public.notifications to authenticated;
create policy notifications_select_own on public.notifications for select to authenticated
  using (user_id = (select auth.uid()));
create policy notifications_select_admin on public.notifications for select to authenticated
  using ((select private.is_admin()));

alter table public.platform_settings
  add column reminder_hours_before integer not null default 24 check (reminder_hours_before between 1 and 168);

-- -----------------------------------------------------------------------------
-- Instructor submits (or edits) the progress note after a lesson.
-- One call: saves the note, marks the lesson completed, and records the
-- instructor's pay for it (rate × minutes, once). Returns true the first time,
-- so the app knows to notify the parent.
-- -----------------------------------------------------------------------------
create or replace function public.submit_lesson_note(
  p_booking_id uuid,
  p_skills jsonb,
  p_summary text,
  p_next_focus text default null
)
returns boolean
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_uid uuid := (select auth.uid());
  v_booking public.bookings;
  v_first boolean;
  v_rate integer;
begin
  if not private.is_booking_instructor(p_booking_id) then
    raise exception 'not your lesson' using errcode = '42501';
  end if;

  select * into v_booking from public.bookings where id = p_booking_id for update;
  if v_booking.status not in ('confirmed', 'completed') then
    raise exception 'this lesson is %', v_booking.status using errcode = 'SB002';
  end if;
  if now() < v_booking.starts_at then
    raise exception 'You can write the note once the lesson has started' using errcode = 'SB005';
  end if;
  if p_skills is null or jsonb_typeof(p_skills) <> 'object' then
    raise exception 'skills must be an object' using errcode = '22023';
  end if;
  if length(trim(coalesce(p_summary, ''))) = 0 then
    raise exception 'Add a short comment for the family' using errcode = '22023';
  end if;
  if length(p_summary) > 2000 or length(coalesce(p_next_focus, '')) > 500 then
    raise exception 'note is too long' using errcode = '22023';
  end if;

  insert into public.lesson_notes (booking_id, instructor_id, skills, summary, next_focus)
  values (p_booking_id, v_uid, p_skills, trim(p_summary), nullif(trim(coalesce(p_next_focus, '')), ''))
  on conflict (booking_id) do update
    set skills = excluded.skills, summary = excluded.summary, next_focus = excluded.next_focus, updated_at = now()
  returning (xmax = 0) into v_first;

  update public.bookings
    set status = 'completed', completed_at = coalesce(completed_at, now())
    where id = p_booking_id;

  select pay_rate_cents_per_hour into v_rate from public.instructor_private where instructor_id = v_uid;
  insert into public.instructor_earnings (instructor_id, booking_id, minutes, rate_cents_per_hour, amount_cents, earned_on)
  values (v_uid, p_booking_id, v_booking.duration_minutes, coalesce(v_rate, 0),
          round(v_booking.duration_minutes * coalesce(v_rate, 0) / 60.0)::integer, private.la_date(v_booking.starts_at))
  on conflict (instructor_id, booking_id) do nothing;

  perform private.write_audit('instructor.submit_note', 'booking', p_booking_id, p_booking_id,
    jsonb_build_object('first_submission', v_first));
  return v_first;
end;
$$;

revoke all on function public.submit_lesson_note(uuid, jsonb, text, text) from public, anon;
grant execute on function public.submit_lesson_note(uuid, jsonb, text, text) to authenticated;

-- ===== 20261017000100_sub_board_and_admin.sql =====
-- =============================================================================
-- Phase 5 · Sub board (instructor hand-offs) + admin settings
--
-- The sub board is enforced here, not in the app:
--   * only the assigned instructor can post their own upcoming, confirmed lesson;
--   * the board row carries zone / neighborhood / time / ages / levels only;
--   * a claimer must be an active instructor who covers the zone, teaches every
--     swimmer's level and age, and is free (travel buffer + no overlap);
--   * when sub_board_requires_approval is on, the claim waits for an admin;
--   * filling the shift moves the booking to the new instructor in the same
--     transaction, so the old instructor loses access at once;
--   * a sub never unlocks family contact details (contact_shared ignores
--     lessons covered from the board).
-- =============================================================================

-- -----------------------------------------------------------------------------
-- Settings
-- -----------------------------------------------------------------------------
alter table public.platform_settings
  add column sub_board_min_notice_hours integer not null default 2 check (sub_board_min_notice_hours between 0 and 168),
  add column day_pass_enabled boolean not null default true,
  add column partner_club_name text check (partner_club_name is null or length(partner_club_name) <= 80);

-- One pending invite per email.
drop index if exists public.instructor_invites_email_idx;
create unique index instructor_invites_email_pending_idx on public.instructor_invites (lower(email)) where accepted_at is null;

alter table public.open_shifts
  add column decision_note text check (decision_note is null or length(decision_note) <= 500);

-- -----------------------------------------------------------------------------
-- Helpers
-- -----------------------------------------------------------------------------

-- Can this instructor teach these swimmers in this zone? Mirrors qualifies() in
-- src/lib/scheduling/engine.ts.
create or replace function private.instructor_qualified_for_booking(p_instructor_id uuid, p_booking_id uuid)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select exists (
    select 1
    from public.instructors i
    join public.bookings b on b.id = p_booking_id
    where i.id = p_instructor_id
      and i.is_active
      and exists (select 1 from public.instructor_zones z where z.instructor_id = i.id and z.zone_id = b.zone_id)
      and b.children_count <= i.max_children_per_lesson
      and not exists (
        select 1
        from public.booking_children bc
        join public.children c on c.id = bc.child_id
        where bc.booking_id = b.id
          and (
            not (c.swim_level = any (i.levels_taught))
            or (c.birth_date is not null
                and (extract(year from age(private.la_date(b.starts_at), c.birth_date)) * 12
                     + extract(month from age(private.la_date(b.starts_at), c.birth_date))) < i.min_child_age_months)
          )
      )
  )
$$;

-- First live booking that would collide with (instructor, zone, start, end),
-- honoring travel buffers. Same rule as the bookings_enforce_travel_buffer trigger.
create or replace function private.instructor_schedule_conflict(
  p_instructor_id uuid, p_zone_id uuid, p_starts_at timestamptz, p_ends_at timestamptz, p_exclude_booking uuid
)
returns uuid
language sql
stable
security definer
set search_path = ''
as $$
  select b.id
  from public.bookings b
  where b.instructor_id = p_instructor_id
    and b.id is distinct from p_exclude_booking
    and b.status in ('pending_payment', 'pending_instructor', 'confirmed', 'completed')
    and b.starts_at < p_ends_at + make_interval(mins => private.travel_buffer_minutes(p_zone_id, b.zone_id))
    and p_starts_at < b.ends_at + make_interval(mins => private.travel_buffer_minutes(b.zone_id, p_zone_id))
  limit 1
$$;

-- Why this instructor can't take this shift (null = they can).
create or replace function private.open_shift_blocker(p_shift public.open_shifts, p_instructor_id uuid)
returns text
language sql
stable
security definer
set search_path = ''
as $$
  select case
    when p_shift.released_by = p_instructor_id then 'This is your lesson'
    when p_shift.starts_at <= now() then 'This lesson has already started'
    when not private.instructor_qualified_for_booking(p_instructor_id, p_shift.booking_id)
      then 'Outside your zones, swimmer levels or ages'
    when private.instructor_schedule_conflict(p_instructor_id, p_shift.zone_id, p_shift.starts_at, p_shift.ends_at, p_shift.booking_id) is not null
      then 'You have a lesson too close to this one'
    else null
  end
$$;

-- Reassign the booking to the sub. The shift is marked filled first, so the
-- bookings trigger below doesn't treat the reassignment as a cancellation.
create or replace function private.fill_open_shift(p_shift_id uuid, p_instructor_id uuid)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_shift public.open_shifts;
begin
  update public.open_shifts
    set status = 'filled', claimed_by = p_instructor_id, claimed_at = coalesce(claimed_at, now())
    where id = p_shift_id
    returning * into v_shift;

  update public.bookings
    set instructor_id = p_instructor_id
    where id = v_shift.booking_id and status = 'confirmed' and instructor_id = v_shift.released_by;
  if not found then
    raise exception 'this lesson changed and can no longer be covered' using errcode = 'SB002';
  end if;
end;
$$;

-- -----------------------------------------------------------------------------
-- Instructor: post my lesson to the board
-- -----------------------------------------------------------------------------
create or replace function public.release_lesson_to_board(p_booking_id uuid, p_reason text default null)
returns uuid
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_uid uuid := (select auth.uid());
  v_booking public.bookings;
  v_notice integer;
  v_summary jsonb;
  v_id uuid;
begin
  if not private.is_booking_instructor(p_booking_id) then
    raise exception 'not your lesson' using errcode = '42501';
  end if;
  select * into v_booking from public.bookings where id = p_booking_id for update;
  if v_booking.status <> 'confirmed' then
    raise exception 'only confirmed lessons can be posted (this one is %)', v_booking.status using errcode = 'SB002';
  end if;
  select sub_board_min_notice_hours into v_notice from public.platform_settings;
  if v_booking.starts_at < now() + make_interval(hours => v_notice) then
    raise exception 'This lesson is less than % hours away — please contact the owner directly', v_notice using errcode = 'SB006';
  end if;
  if exists (select 1 from public.open_shifts s where s.booking_id = p_booking_id and s.status in ('open', 'pending_approval')) then
    raise exception 'this lesson is already on the board' using errcode = 'SB003';
  end if;

  -- Ages + levels only. No names, no address.
  select jsonb_build_object(
    'zone', (select z.code from public.zones z where z.id = v_booking.zone_id),
    'duration_minutes', v_booking.duration_minutes,
    'swimmers', coalesce(jsonb_agg(jsonb_build_object(
        'age', case when c.birth_date is null then null else extract(year from age(private.la_date(v_booking.starts_at), c.birth_date))::integer end,
        'swim_level', c.swim_level) order by c.birth_date), '[]'::jsonb))
  into v_summary
  from public.booking_children bc join public.children c on c.id = bc.child_id
  where bc.booking_id = p_booking_id;

  insert into public.open_shifts (booking_id, released_by, reason, status, zone_id, neighborhood, starts_at, ends_at, lesson_summary)
  values (p_booking_id, v_uid, nullif(left(trim(coalesce(p_reason, '')), 300), ''), 'open',
          v_booking.zone_id, v_booking.neighborhood, v_booking.starts_at, v_booking.ends_at, v_summary)
  returning id into v_id;

  perform private.write_audit('instructor.release_to_board', 'open_shift', v_id, p_booking_id, jsonb_build_object('reason', p_reason));
  return v_id;
end;
$$;

-- Instructor: take my lesson back off the board (before anyone has been approved).
create or replace function public.withdraw_open_shift(p_shift_id uuid)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_shift public.open_shifts;
begin
  if not private.is_active_instructor() then
    raise exception 'not an active instructor' using errcode = '42501';
  end if;
  update public.open_shifts set status = 'cancelled'
    where id = p_shift_id and released_by = (select auth.uid()) and status in ('open', 'pending_approval')
    returning * into v_shift;
  if not found then
    raise exception 'nothing to withdraw' using errcode = 'P0002';
  end if;
  perform private.write_audit('instructor.withdraw_from_board', 'open_shift', p_shift_id, v_shift.booking_id, '{}'::jsonb);
end;
$$;

-- -----------------------------------------------------------------------------
-- Instructor: what's on the board for me (with "can I take it?" per row).
-- -----------------------------------------------------------------------------
create or replace function public.sub_board_shifts()
returns table (
  id uuid, zone_code text, neighborhood text, starts_at timestamptz, ends_at timestamptz,
  lesson_summary jsonb, released_by_first_name text, can_claim boolean, blocked_reason text
)
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_uid uuid := (select auth.uid());
begin
  if not private.is_active_instructor() then
    return;
  end if;
  return query
    select s.id, z.code, s.neighborhood, s.starts_at, s.ends_at, s.lesson_summary, i.first_name,
           private.open_shift_blocker(s, v_uid) is null, private.open_shift_blocker(s, v_uid)
    from public.open_shifts s
    join public.zones z on z.id = s.zone_id
    join public.instructors i on i.id = s.released_by
    where s.status = 'open'
      and s.released_by <> v_uid
      and s.starts_at > now()
      and exists (select 1 from public.instructor_zones iz where iz.instructor_id = v_uid and iz.zone_id = s.zone_id)
    order by s.starts_at;
end;
$$;

-- -----------------------------------------------------------------------------
-- Instructor: claim. Fills immediately, or waits for the owner's approval.
-- -----------------------------------------------------------------------------
create or replace function public.claim_open_shift(p_shift_id uuid)
returns public.open_shift_status
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_uid uuid := (select auth.uid());
  v_shift public.open_shifts;
  v_blocker text;
  v_needs_approval boolean;
begin
  if not private.is_active_instructor() then
    raise exception 'not an active instructor' using errcode = '42501';
  end if;
  select * into v_shift from public.open_shifts where id = p_shift_id for update;
  if not found or not private.instructor_covers_zone(v_shift.zone_id) then
    raise exception 'shift not found' using errcode = 'P0002';
  end if;
  if v_shift.status <> 'open' then
    raise exception 'Someone already picked this one up' using errcode = 'SB002';
  end if;

  -- Serialize against other bookings for this instructor, then check.
  perform pg_advisory_xact_lock(hashtextextended('instructor-schedule:' || v_uid::text, 0));
  v_blocker := private.open_shift_blocker(v_shift, v_uid);
  if v_blocker is not null then
    raise exception '%', v_blocker using errcode = 'SB001';
  end if;

  select sub_board_requires_approval into v_needs_approval from public.platform_settings;
  if v_needs_approval then
    update public.open_shifts set status = 'pending_approval', claimed_by = v_uid, claimed_at = now() where id = p_shift_id;
  else
    perform private.fill_open_shift(p_shift_id, v_uid);
  end if;

  perform private.write_audit('instructor.claim_shift', 'open_shift', p_shift_id, v_shift.booking_id,
    jsonb_build_object('needs_approval', v_needs_approval));
  return case when v_needs_approval then 'pending_approval'::public.open_shift_status else 'filled'::public.open_shift_status end;
end;
$$;

-- -----------------------------------------------------------------------------
-- Admin: approve or turn down a claim. Turning down puts the lesson back on
-- the board for someone else.
-- -----------------------------------------------------------------------------
create or replace function public.decide_open_shift(p_shift_id uuid, p_approve boolean, p_note text default null)
returns public.open_shift_status
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_shift public.open_shifts;
  v_blocker text;
begin
  if not private.is_admin() then
    raise exception 'admins only' using errcode = '42501';
  end if;
  select * into v_shift from public.open_shifts where id = p_shift_id for update;
  if not found then
    raise exception 'shift not found' using errcode = 'P0002';
  end if;
  if v_shift.status <> 'pending_approval' then
    raise exception 'this shift is %', v_shift.status using errcode = 'SB002';
  end if;

  update public.open_shifts
    set decided_by = (select auth.uid()), decided_at = now(), decision_note = nullif(left(trim(coalesce(p_note, '')), 500), '')
    where id = p_shift_id;

  if p_approve then
    perform pg_advisory_xact_lock(hashtextextended('instructor-schedule:' || v_shift.claimed_by::text, 0));
    v_blocker := private.open_shift_blocker(v_shift, v_shift.claimed_by);
    if v_blocker is not null then
      raise exception 'Can''t approve: %', lower(v_blocker) using errcode = 'SB001';
    end if;
    perform private.fill_open_shift(p_shift_id, v_shift.claimed_by);
  else
    update public.open_shifts set status = 'open', claimed_by = null, claimed_at = null where id = p_shift_id;
  end if;

  perform private.write_audit(case when p_approve then 'admin.approve_shift' else 'admin.reject_shift' end,
    'open_shift', p_shift_id, v_shift.booking_id, jsonb_build_object('claimed_by', v_shift.claimed_by, 'note', p_note));
  return case when p_approve then 'filled'::public.open_shift_status else 'open'::public.open_shift_status end;
end;
$$;

-- Service: instructors who could take a newly posted shift (for the "up for
-- grabs" message).
create or replace function public.open_shift_candidates(p_shift_id uuid)
returns setof uuid
language sql
stable
security definer
set search_path = ''
as $$
  select i.id
  from public.open_shifts s
  join public.instructor_zones iz on iz.zone_id = s.zone_id
  join public.instructors i on i.id = iz.instructor_id
  where s.id = p_shift_id
    and s.status = 'open'
    and i.is_active
    and private.has_accepted_current_terms(i.id)
    and private.open_shift_blocker(s, i.id) is null
$$;

-- Service: shifts whose lesson has started are no longer claimable.
create or replace function public.expire_open_shifts()
returns integer
language sql
security definer
set search_path = ''
as $$
  with expired as (
    update public.open_shifts set status = 'expired'
    where status in ('open', 'pending_approval') and starts_at <= now()
    returning 1
  )
  select count(*)::integer from expired
$$;

revoke all on function public.release_lesson_to_board(uuid, text) from public, anon;
revoke all on function public.withdraw_open_shift(uuid) from public, anon;
revoke all on function public.sub_board_shifts() from public, anon;
revoke all on function public.claim_open_shift(uuid) from public, anon;
revoke all on function public.decide_open_shift(uuid, boolean, text) from public, anon;
revoke all on function public.open_shift_candidates(uuid) from public, anon, authenticated;
revoke all on function public.expire_open_shifts() from public, anon, authenticated;
grant execute on function public.release_lesson_to_board(uuid, text) to authenticated;
grant execute on function public.withdraw_open_shift(uuid) to authenticated;
grant execute on function public.sub_board_shifts() to authenticated;
grant execute on function public.claim_open_shift(uuid) to authenticated;
grant execute on function public.decide_open_shift(uuid, boolean, text) to authenticated;
grant execute on function public.open_shift_candidates(uuid) to service_role;
grant execute on function public.expire_open_shifts() to service_role;

-- -----------------------------------------------------------------------------
-- Any other change to the lesson (cancelled, moved, reassigned by the owner)
-- takes it off the board.
-- -----------------------------------------------------------------------------
create or replace function private.bookings_close_open_shifts()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if new.status is distinct from old.status
     or new.starts_at is distinct from old.starts_at
     or new.ends_at is distinct from old.ends_at
     or new.instructor_id is distinct from old.instructor_id then
    update public.open_shifts set status = 'cancelled'
      where booking_id = new.id and status in ('open', 'pending_approval');
  end if;
  return new;
end;
$$;

create trigger bookings_close_open_shifts
  after update of status, starts_at, ends_at, instructor_id on public.bookings
  for each row execute function private.bookings_close_open_shifts();

-- -----------------------------------------------------------------------------
-- Contact sharing: covering a lesson from the sub board never unlocks the
-- family's phone/email for the sub.
-- -----------------------------------------------------------------------------
create or replace function private.contact_shared(p_parent_id uuid, p_instructor_id uuid)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select (select s.contact_sharing from public.platform_settings s) = 'package_instructor'
    and exists (
      select 1
      from public.bookings b
      join public.packages p on p.id = b.package_id
      where b.parent_id = p_parent_id
        and b.instructor_id = p_instructor_id
        and b.status in ('confirmed', 'completed')
        and p.status in ('active', 'exhausted')
        and not exists (
          select 1 from public.open_shifts s
          where s.booking_id = b.id and s.status = 'filled' and s.claimed_by = p_instructor_id
        )
    )
$$;

-- Internal helpers: callable only from the SECURITY DEFINER functions above.
revoke all on function private.instructor_qualified_for_booking(uuid, uuid) from public, anon, authenticated;
revoke all on function private.instructor_schedule_conflict(uuid, uuid, timestamptz, timestamptz, uuid) from public, anon, authenticated;
revoke all on function private.open_shift_blocker(public.open_shifts, uuid) from public, anon, authenticated;
revoke all on function private.fill_open_shift(uuid, uuid) from public, anon, authenticated;
revoke all on function private.bookings_close_open_shifts() from public, anon, authenticated;
revoke all on function private.contact_shared(uuid, uuid) from public, anon, authenticated;

-- ===== 20261022000100_hsa_fsa_truemed.sql =====
-- =============================================================================
-- HSA/FSA payments through Truemed
--
-- Truemed is the merchant of record for HSA/FSA transactions: the family is
-- redirected to Truemed (eligibility survey + HSA/FSA card), and Truemed's
-- webhook tells us when the payment is captured. Off until the owner has a
-- Truemed account (TRUEMED_API_KEY) and turns it on in Admin → Policies.
-- =============================================================================

alter table public.payments
  add column processor text not null default 'stripe' check (processor in ('stripe', 'truemed', 'manual')),
  add column processor_session_id text unique;

alter table public.platform_settings
  add column hsa_fsa_enabled boolean not null default false;

-- ===== 20261022000200_lock_platform_settings.sql =====
-- =============================================================================
-- Public pages read a handful of policy settings; internal operating values
-- (default instructor pay, buffers, hold times, offer timing…) stay server-side.
-- Column-level SELECT replaces the table-wide grant for anon/authenticated.
-- The service role (server code, admin pages) still reads everything.
-- =============================================================================
revoke select on public.platform_settings from anon, authenticated;
grant select (
  id,
  timezone,
  cancellation_window_hours,
  late_cancel_refund_pct,
  booking_request_window_hours,
  min_booking_notice_hours,
  max_booking_horizon_days,
  max_children_per_lesson,
  recurring_term_weeks,
  instructor_terms_version,
  sub_board_requires_approval,
  sub_board_min_notice_hours,
  day_pass_enabled,
  partner_club_name,
  hsa_fsa_enabled,
  support_email,
  support_phone
) on public.platform_settings to anon, authenticated;

-- ===== 20261022000300_security_hardening.sql =====
-- =============================================================================
-- Security hardening (code review, 2026-10-22)
--
-- 1. Promo codes: one use is claimed atomically inside create_booking_hold
--    (previously only after payment, and never for $0 checkouts), and handed
--    back when an unpaid hold lapses. Unknown/exhausted codes fail the hold.
-- 2. Refund bookkeeping: refunded_cents is incremented in SQL, never
--    read-modify-written by the app (record_refund).
-- 3. Client insulation: direct inserts into messages are closed until the
--    contact-info filter exists (chat isn't offered), instructor bios and
--    first names can't carry phone numbers / emails / handles, and instructors
--    see only live bookings (no parent-written cancellation reasons).
-- =============================================================================

alter table public.payments add column discount_code_id uuid references public.discount_codes (id) on delete set null;

-- Codes are matched exactly (no pattern matching), stored uppercase.
update public.discount_codes set code = upper(trim(code)) where code <> upper(trim(code));
alter table public.discount_codes add constraint discount_codes_code_format check (code ~ '^[A-Z0-9_-]{3,30}$');

create or replace function public.create_booking_hold(p jsonb)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_parent uuid := (p ->> 'parent_id')::uuid;
  v_kind text := p ->> 'kind';
  v_amount integer := coalesce((p ->> 'amount_cents')::integer, 0);
  v_children integer := jsonb_array_length(p -> 'child_ids');
  v_hold timestamptz;
  v_payment_id uuid;
  v_package_id uuid;
  v_series_id uuid;
  v_booking_id uuid;
  v_ids uuid[] := '{}';
  v_occ jsonb;
  v_loc jsonb := p -> 'location';
begin
  if v_kind not in ('single', 'package', 'recurring', 'package_credit') then
    raise exception 'invalid kind %', v_kind using errcode = '22023';
  end if;
  if v_children < 1 or exists (
    select 1 from jsonb_array_elements_text(p -> 'child_ids') c
    where not exists (select 1 from public.children ch where ch.id = c::uuid and ch.parent_id = v_parent and ch.is_active)
  ) then
    raise exception 'swimmers must belong to this family' using errcode = '22023';
  end if;

  -- Claim one use of the promo code in the same transaction as the hold, so
  -- parallel checkouts can't exceed max_redemptions and $0 checkouts count too.
  -- Released again if the checkout lapses unpaid (release_booking_hold).
  if p ->> 'discount_code_id' is not null and not public.redeem_discount_code((p ->> 'discount_code_id')::uuid) then
    raise exception 'That code is no longer available.' using errcode = 'SB007';
  end if;

  select now() + make_interval(mins => s.payment_hold_minutes) into v_hold from public.platform_settings s;

  if v_kind = 'package' then
    insert into public.packages (parent_id, offering_id, lesson_count, lessons_remaining, duration_minutes, children_count, zone_id,
                                 unit_price_cents, discount_pct, total_cents, status)
    values (v_parent, (p #>> '{package,offering_id}')::uuid, (p #>> '{package,lesson_count}')::integer,
            (p #>> '{package,lesson_count}')::integer - 1,  -- the first lesson is booked now
            (p #>> '{package,duration_minutes}')::integer, v_children, (p ->> 'zone_id')::uuid,
            (p #>> '{package,unit_price_cents}')::integer, (p #>> '{package,discount_pct}')::numeric,
            (p #>> '{package,total_cents}')::integer, 'pending_payment')
    returning id into v_package_id;
  elsif v_kind = 'recurring' then
    insert into public.booking_series (parent_id, instructor_id, zone_id, weekday, start_time, duration_minutes, children_count,
                                       starts_on, ends_on, discount_pct, status)
    values (v_parent, (p ->> 'instructor_id')::uuid, (p ->> 'zone_id')::uuid, (p #>> '{series,weekday}')::smallint,
            (p #>> '{series,start_time}')::time, (p #>> '{series,duration_minutes}')::integer, v_children,
            (p #>> '{series,starts_on}')::date, (p #>> '{series,ends_on}')::date, (p #>> '{series,discount_pct}')::numeric,
            case when v_amount > 0 then 'pending_payment'::public.series_status else 'active'::public.series_status end)
    returning id into v_series_id;
  elsif v_kind = 'package_credit' then
    v_package_id := (p ->> 'package_id')::uuid;
    perform public.consume_package_credit(v_package_id, v_parent);
  end if;

  if v_amount > 0 then
    insert into public.payments (parent_id, package_id, series_id, amount_cents, currency, kind, description, status, discount_code_id)
    values (v_parent, v_package_id, v_series_id, v_amount, coalesce(p ->> 'currency', 'usd'),
            case v_kind when 'package' then 'package' when 'recurring' then 'series' else 'booking' end,
            left(p ->> 'description', 500), 'pending', (p ->> 'discount_code_id')::uuid)
    returning id into v_payment_id;
  end if;

  for v_occ in select value from jsonb_array_elements(p -> 'occurrences') loop
    insert into public.bookings (parent_id, instructor_id, requested_instructor_id, zone_id, neighborhood, starts_at, ends_at,
                                 status, kind, series_id, package_id, children_count, is_neighborhood_slot, hold_expires_at,
                                 source, created_by, payment_id)
    values (v_parent, (p ->> 'instructor_id')::uuid, (p ->> 'requested_instructor_id')::uuid, (p ->> 'zone_id')::uuid,
            p ->> 'neighborhood', (v_occ ->> 'starts_at')::timestamptz, (v_occ ->> 'ends_at')::timestamptz,
            'pending_payment',
            case v_kind when 'recurring' then 'recurring'::public.booking_kind
                        when 'single' then 'single'::public.booking_kind
                        else 'package'::public.booking_kind end,
            v_series_id, v_package_id, v_children, coalesce((v_occ ->> 'is_neighborhood_slot')::boolean, false),
            case when v_amount > 0 then v_hold end, 'web', v_parent,
            case when v_kind in ('single', 'recurring') then v_payment_id end)
    returning id into v_booking_id;

    insert into public.booking_children (booking_id, child_id)
    select v_booking_id, c::uuid from jsonb_array_elements_text(p -> 'child_ids') c;

    insert into public.booking_locations (booking_id, address_line1, address_line2, city, postal_code, lat, lng, google_place_id, access_notes)
    values (v_booking_id, v_loc ->> 'address_line1', nullif(v_loc ->> 'address_line2', ''), v_loc ->> 'city', v_loc ->> 'postal_code',
            (v_loc ->> 'lat')::double precision, (v_loc ->> 'lng')::double precision, v_loc ->> 'google_place_id',
            nullif(v_loc ->> 'access_notes', ''));

    insert into public.booking_pricing (booking_id, currency, base_cents, extra_children_cents, travel_fee_cents,
                                        neighborhood_discount_cents, package_discount_cents, series_discount_cents,
                                        promo_discount_cents, discount_code_id, total_cents, snapshot)
    values (v_booking_id, coalesce(p ->> 'currency', 'usd'),
            coalesce((v_occ #>> '{pricing,base_cents}')::integer, 0),
            coalesce((v_occ #>> '{pricing,extra_children_cents}')::integer, 0),
            coalesce((v_occ #>> '{pricing,travel_fee_cents}')::integer, 0),
            coalesce((v_occ #>> '{pricing,neighborhood_discount_cents}')::integer, 0),
            coalesce((v_occ #>> '{pricing,package_discount_cents}')::integer, 0),
            coalesce((v_occ #>> '{pricing,series_discount_cents}')::integer, 0),
            coalesce((v_occ #>> '{pricing,promo_discount_cents}')::integer, 0),
            (p ->> 'discount_code_id')::uuid,
            (v_occ #>> '{pricing,total_cents}')::integer,
            coalesce(p -> 'pricing_snapshot', '{}'::jsonb));

    v_ids := v_ids || v_booking_id;
  end loop;

  if v_payment_id is not null and v_kind = 'single' then
    update public.payments set booking_id = v_ids[1] where id = v_payment_id;
  end if;

  return jsonb_build_object('payment_id', v_payment_id, 'booking_ids', to_jsonb(v_ids), 'package_id', v_package_id, 'series_id', v_series_id);
end;
$$;

create or replace function public.release_booking_hold(p_payment_id uuid)
returns integer
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_payment public.payments;
  v_count integer;
begin
  update public.payments set status = 'cancelled'
    where id = p_payment_id and status = 'pending'
    returning * into v_payment;
  if not found then
    return 0;
  end if;

  update public.bookings set status = 'expired', hold_expires_at = null
    where status = 'pending_payment'
      and (payment_id = p_payment_id or (v_payment.package_id is not null and package_id = v_payment.package_id));
  get diagnostics v_count = row_count;

  -- Hand back the promo use claimed when the hold was created.
  if v_payment.discount_code_id is not null then
    update public.discount_codes set redemptions = greatest(redemptions - 1, 0) where id = v_payment.discount_code_id;
  end if;

  update public.packages set status = 'expired' where id = v_payment.package_id and status = 'pending_payment';
  update public.booking_series set status = 'cancelled' where id = v_payment.series_id and status = 'pending_payment';
  return v_count;
end;
$$;

revoke all on function public.create_booking_hold(jsonb) from public, anon, authenticated;
revoke all on function public.release_booking_hold(uuid) from public, anon, authenticated;
grant execute on function public.create_booking_hold(jsonb) to service_role;
grant execute on function public.release_booking_hold(uuid) to service_role;

-- -----------------------------------------------------------------------------
-- 2. Atomic refund bookkeeping. Returns the new refunded total; refuses to
--    exceed the payment amount.
-- -----------------------------------------------------------------------------
create or replace function public.record_refund(p_payment_id uuid, p_amount_cents integer, p_refund_id text)
returns integer
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_total integer;
begin
  if p_amount_cents <= 0 then
    raise exception 'refund must be positive' using errcode = '22023';
  end if;
  update public.payments
    set refunded_cents = refunded_cents + p_amount_cents,
        status = case when refunded_cents + p_amount_cents >= amount_cents then 'refunded'::public.payment_status else 'partially_refunded'::public.payment_status end,
        stripe_refund_ids = case when p_refund_id = any (stripe_refund_ids) then stripe_refund_ids else stripe_refund_ids || p_refund_id end
    where id = p_payment_id
      and refunded_cents + p_amount_cents <= amount_cents
      and not (p_refund_id = any (stripe_refund_ids))
    returning refunded_cents into v_total;
  if not found then
    -- Already recorded (same refund id) or would exceed the amount.
    select refunded_cents into v_total from public.payments where id = p_payment_id;
  end if;
  return v_total;
end;
$$;
revoke all on function public.record_refund(uuid, integer, text) from public, anon, authenticated;
grant execute on function public.record_refund(uuid, integer, text) to service_role;

-- -----------------------------------------------------------------------------
-- 3a. Messages: chat isn't part of the product; close direct inserts so the
--     table can't become an unfiltered contact-exchange channel.
-- -----------------------------------------------------------------------------
revoke insert on public.messages from authenticated, anon;

-- 3b. Instructor bio / first name: no phone numbers, emails, URLs or handles.
create or replace function private.has_contact_info(p_text text)
returns boolean
language sql
immutable
set search_path = ''
as $$
  select p_text is not null and (
    p_text ~* '[a-z0-9._%+-]+\s*(@|\(at\)|\[at\]| at )\s*[a-z0-9-]+\s*(\.|\(dot\)| dot )\s*[a-z]{2,}'
    or p_text ~ '(\+?1[\s.-]?)?\(?[0-9]{3}\)?[\s.-]?[0-9]{3}[\s.-]?[0-9]{4}'
    or p_text ~* '(https?://|www\.|\.(com|net|org|io|me|co)\y)'
    or p_text ~* '(^|\s)@[a-z0-9_.]{2,}'
    or p_text ~* '\m(venmo|zelle|cash ?app|paypal|instagram|insta|ig|snapchat|whatsapp|telegram|tiktok)\M'
  )
$$;
revoke all on function private.has_contact_info(text) from public, anon;
-- The check constraints run as the instructor saving their profile.
grant execute on function private.has_contact_info(text) to authenticated, service_role;

alter table public.instructors
  add constraint instructors_bio_no_contact_info check (not private.has_contact_info(bio)) not valid,
  add constraint instructors_first_name_no_contact_info check (not private.has_contact_info(first_name)) not valid;

-- 3c. Instructors read only live bookings through RLS (cancelled/expired rows can
--     carry a parent-written cancellation reason).
drop policy if exists bookings_select_instructor on public.bookings;
create policy bookings_select_instructor on public.bookings for select to authenticated
  using (
    instructor_id = (select auth.uid())
    and status in ('pending_instructor', 'confirmed', 'completed', 'no_show')
    and (select private.is_active_instructor())
  );

-- 4. Day pass: rate-limit per network as well as per email. Stores a salted
--    one-way hash of the IP, never the IP itself.
alter table public.day_pass_inquiries add column if not exists client_key text;
create index if not exists day_pass_inquiries_client_key_idx on public.day_pass_inquiries (client_key, created_at) where client_key is not null;
create index if not exists day_pass_inquiries_email_idx on public.day_pass_inquiries (contact_email, created_at);

-- ===== 20261023000100_package_auto_renew.sql =====
-- =============================================================================
-- Package auto-renew (opt-in).
--
-- A family can tick "auto-renew" when buying a package by card. When the last
-- lesson of that package has been booked, the renewal is scheduled for after
-- that lesson; the family is emailed at least 3 days before the charge and can
-- turn it off from their account at any time. The saved card (Stripe payment
-- method) is charged off-session and the same package is added to the account.
-- =============================================================================

alter table public.packages
  add column auto_renew boolean not null default false,
  add column auto_renew_consented_at timestamptz,
  -- The regular package price (no one-time promo), as shown when they opted in.
  add column renewal_amount_cents integer check (renewal_amount_cents > 0),
  add column renewal_payment_method_id text,
  add column renewal_charge_at timestamptz,
  add column renewal_reminded_at timestamptz,
  add column renewal_started_at timestamptz,
  add column renewal_failed_at timestamptz,
  add column renewal_failure text,
  add column renewed_from_package_id uuid references public.packages (id) on delete set null,
  add column renewed_to_package_id uuid references public.packages (id) on delete set null;

create index packages_auto_renew_idx on public.packages (id)
  where auto_renew and renewed_to_package_id is null and renewal_started_at is null;

-- Parents read their own packages through RLS already; the saved card
-- reference stays server-side.
revoke select on public.packages from authenticated;
grant select (
  id, parent_id, offering_id, lesson_count, lessons_remaining, duration_minutes, children_count, zone_id,
  unit_price_cents, discount_pct, total_cents, status, purchased_at, expires_at, created_at, updated_at,
  auto_renew, auto_renew_consented_at, renewal_amount_cents, renewal_charge_at, renewal_reminded_at, renewal_started_at,
  renewal_failed_at, renewed_from_package_id, renewed_to_package_id
) on public.packages to authenticated;
